Next, for a function $\mathbf{m}^{\mathbf{e}}_{\bm{\Lambda}}:\mathbb{R}^d\to\mathbb{C}$, we define the \emph{shifted Fourier  operator} $\bm{\Lambda}:\bmrm{L}(\mathbb{R}^d,\mathbf{e})\to\bmrm{L}(\mathbb{R}^d,\mathbf{e})$ with multiplier $\mathbf{m}^{\mathbf{e}}_{\bm{\Lambda}}$ by
	\begin{equation}
		\mathcal{F}^{\mathbf{e}}_{\bm{\Lambda} \mathbf{f}}(\bm{\xi})=\mathbf{m}^{\mathbf{e}}_{\bm{\Lambda}}\left(\bm{\xi}\right)\mathcal{F}^{\mathbf{e}}_{\mathbf{f}}(\bm{\xi}), \ \bm{\xi}\in\mathbb{R}^d.
	\end{equation}

\begin{eqnarray*}
	f&\asymp &g  \text{ means that $\exists  c>0$ such that  $c^{-1}\leqslant\frac{f}{g}\leqslant c$,} \\
	f&\overset{a}{\sim}& g \text{ means that $\lim_{x\to a}\frac{f(x)}{g(x)}=1$ for some $a\in[0,\infty]$}, \\
	f(x)&\overset{a}{=}&\mathrm{O}(g(x)) \text{ means that $\limsup_{x\to a}\left|\frac{f(x)}{g(x)}\right|<\infty$},\\
	f(x)&\overset{a}{=}&\mathrm{o}(g(x)) \text{ means that $\lim_{x\to a}\frac{f(x)}{g(x)}=0$}.
\end{eqnarray*}

Next, for any $\phi\in\mathbf{B}$, let us denote by $W_{\phi}$ the so-called Bernstein-gamma function associated to $\phi$, that is the  unique positive definite function, i.e.~the Mellin transform of a positive random variable, satisfying the functional equation
\begin{equation} \phantomsection\label{eq:BG_receq}
W_{\phi}(z+1)=\phi(z)W_\phi(z), \ \  z\in\mathbb{C}_{(0,\infty)}, \textrm{ and } W_\phi(1)=1.
\end{equation}

\begin{equation}\phantomsection\label{eq:W_Zerofree}
W_{\phi} \mbox{ is analytic  and zero-free (at least) on }  \mathbb{C}_{[0,\infty)}.
\end{equation}

For two Hilbert spaces $\mathrm{H}_1,\mathrm{H}_2$ and $A\in\mathscr{D}(\mathrm{H}_1), B\in\mathscr{D}(\mathrm{H}_2)$, we say that \emph{$A$ is weakly similar to $B$} if there exists $\Lambda \in \mathscr{D}_0(\mathrm{H}_2,\mathrm{H}_1)$ such that
\begin{align}\phantomsection\label{eq:ws0}
	A\Lambda =\Lambda B  \ \mbox{ on } \ \mathcal{D}
\end{align}
with $\mathcal{D},\Lambda(\mathcal{D})$ being dense in $\mathrm{H}_2, \mathrm{H}_1$ respectively, and
\begin{align}\phantomsection\label{eq:domains}
	\mathcal{D}\subset\mathbf{D}(B)\cap \mathbf{D}(\Lambda), \ \Lambda(\mathcal{D})\subset\mathbf{D}(A) \ \text{ and } \ B(\mathcal{D})\subset\mathbf{D}(\Lambda).
\end{align}
$\Lambda$ is called a \emph{weak similarity operator}.

	Let $\mathrm{H}_1,\mathrm{H}_2$ be Hilbert spaces and $B\in\mathscr{D}(\mathrm{H}_2)$. We define the \emph{weak similarity orbit} of $B$ in $\mathscr{D}\subset\mathscr{D}(\mathrm{H}_1)$ as the set of all operators $A\in\mathscr{D}$ such that $A$ is weakly similar to $B$. We write
	\begin{align*}
		\mathrm{WS}_{\mathscr{D}}(B)=\{A\in\mathscr{D}; \: \text{$A$ is weakly similar to $B$}\}.
	\end{align*}
When $\mathscr{D}=\mathscr{D}({\rm H}_1)$, we simply denote $\mathrm{WS}(B)=\mathrm{WS}_{\mathscr{D}}(B)$.

We now set up the assumptions and notation that will be in force throughout the paper, and we refer to the remarks below for discussions about their generality.
Let
\begin{align}\phantomsection\label{N_+}
 \mathbf{N}_+(\mathbb{R})=
&\left\{\psi\in\mathbf{N}(\mathbb{R});  \ \liminf_{|\xi|\to\infty}\frac{|\phi_+({\rm{i}}\xi  )|}{|\xi|^{-\kappa}}>0 \ \mbox{for some $\kappa>0$},  \ \frac{W_{\phi_+}(\frac{1}{2}+{\rm{i}}\xi  )}{W_{\phi_-}(\frac{1}{2}+{\rm{i}}\xi  )}={\rm{O}}(1)\right\}
 \end{align}
\begin{align}\phantomsection\label{N_-}
\mathbf{N}_-(\mathbb{R})=\left\{\psi\in\mathbf{N}(\mathbb{R});  \ \overline{\psi}\in\mathbf{N}_+(\mathbb{R})\right\}


\end{align} and
\begin{equation} \label{eq:defNb}\mathbf{N}_b(\mathbb{R})=\mathbf{N}_+(\mathbb{R})\cup\mathbf{N}_-(\mathbb{R}).
\end{equation}

Finally, for any $d\in \mathbb{N}, d\geqslant2,$ we write  $\bm{\psi}=(\psi_1,\ldots,\psi_d)\in\mathbf{N}^d_b(\mathbb{R})$ where
\begin{equation} \label{eq:defNbd}
\mathbf{N}^d_b(\mathbb{R})=\mathbf{N}_b(\mathbb{R})\times \ldots \times \mathbf{N}_b(\mathbb{R}) \quad (d \textrm{ times})
\end{equation}
and, for any $k=1,\ldots,d$, $(\psi_k(0),\sigma_k^2,\mathtt{b}_k,\mu_k)$ is the characteristic quadruplet of $\psi_k$, see \eqref{eq:defLKe}.

We point out that, for $\phi\in\mathbf{B}$, the condition $\liminf\limits_{|\xi|\to\infty}|\xi|^\kappa|\phi({\rm{i}}\xi  )|>0$ has been termed as the \emph{weak non-lattice} property in \cite[(2.29)]{patie2018}, and in particular, it implies that
\begin{equation}\phantomsection\label{eq:zerofree}
  \phi \ \mbox{is zero-free on ${\rm{i}}\mathbb{R}\setminus\{0\}$}.
\end{equation}

In this paper, the weak non-lattice property is used to ensure the moderate growth of certain functions along the lines $\textrm{Re}(z)=a$, $0\leqslant a\leqslant1$, which plays an important role in the proof of our results. We refer to Section \ref{bernstein} for more details.

also define
\begin{equation*}
 \mathcal{D}(\mathbb R) = \{f\in \bmrm{L}(\mathbb{R},e);\: \mathcal{F}_f \textrm{ is entire and satisfies \eqref{eq:udec}}\}
\end{equation*}

\begin{equation} \label{eq:udec}
\hpt{R4}{\textrm{ For any compact } C \subset \mathbb{R},\: \sup_{a \in C}|\mathcal{F}_f(\xi+\mathrm{i} a)|=\mathrm{O}(e^{-(\frac{\pi}{2}+\epsilon)|\xi|}),\: \epsilon>0,}
	\end{equation}
and we write $\bm{\mathcal{D}}(\mathbb R^d)=\otimes_{k=1}^d\mathcal{D}(\mathbb R)$.

\phantomsection\label{thm1:main_thm_1} For any $M\in\mathrm{GL}_d(\mathbb R)$, writing $ \mathscr{A}_M=\{\bm{A}^M_{\mathtt{PDO}}[\bm{\psi}]; \: \bm{\psi}\in\mathbf{N}^d_b(\mathbb R)\}$, we have

			\begin{align*}
				\mathrm{WS}_{\mathscr{A}_M}(\bm{A}_\mathtt{PDO}[\bm\psi_0])=\mathscr{A}_M
			\end{align*}
where $\bm{\psi}_0(\bm{\xi})=(\xi^2_1,\ldots,\xi^2_d)$. More specifically, for any $\bm{\psi}\in\mathbf{N}^d_b(\mathbb R)$ and $M\in\mathrm{GL}_d(\mathbb{R})$, we have
\begin{align} \phantomsection\label{eq:wsob}
	\bm{A}^M_\mathtt{PDO}[\bm\psi]\bm{\Lambda}_{\bm\psi,M}=\bm{\Lambda}_{\bm\psi,M}\bm{A}_\mathtt{PDO}[\bm\psi_0] \ \text{ on } \ \bm{\mathcal{D}}(\mathbb R^d)
\end{align}
where $\bm{\Lambda}_{\bm \psi,M}:\mathbf{D}(\bm{\Lambda}_{\bm \psi,M}) \subset \bmrm{L}(\mathbb R^d,{\bf e})\to \bmrm{L}(\mathbb R^d,{\bf e}_M)$ is such that $\bm{\Lambda}_{\bm\psi,M}{\bf f}(\bm x)=\bm{\Lambda_\psi}{\bf f}(M\bm x)$, and $\bm{\Lambda}_{\bm \psi}$ is a shifted Fourier multiplier operator associated to
\begin{align*}
	\mathbf{m}^{\mathbf{e}}_{\bm{\Lambda}_{\bm\psi}}(\bm{\xi})=\prod_{k=1}^d \frac{W_{\phi_{+,k}}(\frac{1}{2}-\mathrm{i}\xi_k)}{W_{\phi_{-,k}}(\frac{1}{2}+\mathrm{i}\xi_k)}\frac{\Gamma(\frac{1}{2}+\mathrm{i}\xi_k)}{\Gamma(\frac{1}{2}-\mathrm{i}\xi_k)}.
\end{align*}
Moreover, for any $\bm{\psi}\in\mathbf{N}^d_+(\mathbb R)$, $\bm{\Lambda}_{\bm\psi,M}\in\mathscr{B}(\bmrm{L}(\mathbb{R}^d,{\bf e}),\bmrm{L}(\mathbb{R}^d,{\bf e}_M))$.

\phantomsection\label{thm:semigroup_generation}
		\begin{enumerate}
\item \phantomsection\label{it:bessel_generation}
The closure of  $(\bm{A}_\mathtt{PDO}[\bm\psi_0],\mathbf{C}^\infty_c(\mathbb R^d))$ in $\bmrm{L}(\mathbb R^d,{\bf e})$, denoted by $\bm{A}_2[\bm\psi_0]$, generates a self-adjoint $\mathcal{C}_0$-semigroup $\bm{Q} \in \mathcal{C}^+_0(\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}))$.
More specifically, $\bm{Q}$ restricted to  $\mathbf{C}_0(\mathbb R^d)\cap \bmrm{L}(\mathbb R^d,{\bf e})$  extends to the Feller semigroup of the $d$-dimensional log-Bessel process of dimension 2 whose generator is the closure of $(\bm{A}_0, \mathbf{C}^\infty_c(\mathbb R^d))$.
	\item \phantomsection\label{it:bijection}
For any $M\in\mathrm{GL}_d(\mathbb R)$, there exists a one-to-one mapping between the set $\mathscr{A}_M$ and the set
\[ \mathscr{P}_M=\left\{\bm{P}^M[\bm{\psi}]; \: \bm{\psi}\in\mathbf{N}^d_b(\mathbb{R})\right\} \subset \mathcal{C}_0(\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M))\]
such that $\bm{A}^M_\mathtt{2}[\bm\psi]=\bm{A}^M_\mathtt{PDO}[\bm\psi]$ on a dense subset, where  $\bm{A}^M_\mathtt{2}[\bm\psi]$ is the  $\bmrm{L}(\mathbb R^d,\mathbf{e}_M)$-generator of $\bm{P}^M[\bm{\psi}]$.

More specifically,  for any ${\psi}\in \mathbf{N}_+(\mathbb R)$, $A_\mathtt{2}[\psi]$ is the closure of $(A_\mathtt{PDO}[\psi],\Lambda_{\psi}(\mathbf{C}^\infty_c(\mathbb R))$, where $\Lambda_{\psi}\in  \mathscr{B}(\bmrm{L}(\mathbb{R},{e}))$ is defined in \eqref{eq:wsob}, and, otherwise, for any ${\psi}\in \mathbf{N}_b(\mathbb R)\setminus \mathbf{N}_+(\mathbb R)$, $\widehat{{P}}[{\psi}]={P}[{\overline{{\psi}}}]$. The general case is then obtained by tensorization and isomorphism of Hilbert spaces.
	\item \phantomsection\label{it:ws_semigroups} 
For any $M\in\mathrm{GL}_d(\mathbb R)$, we have
\hptg{C16}{
	\begin{equation} \phantomsection\label{eq:ws}
		\mathrm{WS}_{\mathscr{P}_M}(\bm{Q})=\mathscr{P}_M.      
	\end{equation}}
In fact, the set of weak similarity operators is a multiplicative group which entails that $\mathrm{WS}_{\mathscr{P}}$ forms an equivalence class, where $\mathscr{P}=\bigcup_{M\in\mathrm{GL}_d(\mathbb R)}\mathscr{P}_M$. 




			\item \phantomsection\label{it:thm2adj} For any $\bm\psi\in\mathbf{N}^d_b(\mathbb R)$, we have $\widehat{\bm{P}}^M[\bm{\psi}]=\bm{P}^{M}[\overline{\bm{\psi}}]\in \mathscr{P}$, where $\widehat{\bm{P}}^M[\bm{\psi}]$ stands for  the $\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)$-adjoint of $\bm{P}^M[\bm{\psi}]$. Thus, $\bm{P}^M[\bm{\psi}]$ is self-adjoint in $\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)$ if and only if $\overline{\bm{\psi}}=\bm{\psi}$. \vspace{.2cm}
		\end{enumerate}

When $d=1$, $M=\rm{Id}$, the identity matrix, writing simply $P[\psi]=\bm{P}^{\rm{Id}}[\bm{\psi}]$, the identity \eqref{eq:ws} reads as follows
\begin{align}
	{\rm WS}_\mathscr{P}(Q)=\{P[\psi]; \: \psi\in\mathbf{N}_b(\mathbb R)\}
\end{align}
where $Q$ is the semigroup on $\bmrm{L}(\mathbb{R},e)$, $e(x)=e^x, x \in \mathbb{R}$, of the log-squared Bessel process of dimension $2$. Moreover, $P[\psi]$ is the $\bmrm{L}(\mathbb{R},e)$-extension of the log-self-similar Feller semigroup as reviewed in Section \ref{sec:lamp}.

To this end, we denote the multiplication semigroup on $\bmrm{L}(\mathbb{R}^d,\mathbf{e})$ by $(\bm{e}_t)_{t\geqslant 0}$, i.e.~for any $t\geqslant0$,
\begin{align}
	\bm{e}_t \mathbf{f}(\bm{y})={e}^{-t\langle e(-\bm{y}),\bm{1}\rangle}\mathbf{f}(\bm{y}), \;\; \bm{y}\in\mathbb{R}^d, 
\end{align}
where we recall that  $e(-\bm{y})=\left(e^{-y_1}, \ldots, e^{-y_d}\right)$.

\phantomsection\label{th:spectral_decomp}
	Let $\bm{P}^M[\bm{\psi}] \in \mathscr{P}_M$ for some $M\in\mathrm{GL}_d(\mathbb R)$ and $\bm{\psi}=(\psi_1,\ldots,\psi_d)\in\mathbf{N}^d_b(\mathbb{R})$ such that $\psi_k(\xi)=\phi_{+,k}(-\mathrm{i}\xi)\phi_{-,k}(\mathrm{i}\xi)$ for all $1\leqslant k\leqslant d$ and $\xi\in\mathbb{R}$. Then, for all $t\geqslant 0$, 
		\begin{align}\phantomsection\label{eq:spectral_decomp}
			\bm{P}^M_t[\bm{\psi}] =\bm{H}_{\bm{\psi},M}\bm{e}_t \bm{H}^{-1}_{\bm{\psi},M} \ \mbox{ on } \ \mathbf{D}(\bm{H}^{-1}_{\bm{\psi},M})
		\end{align}
		where  $\mathbf{D}(\bm{H}^{-1}_{\bm{\psi},M})=\operatorname{Range}(\bm{H}_{\bm{\psi},M})$ is dense in $\bmrm{L}(\mathbb{R}^d,\mathbf{e}), \
		\bm{H}_{\bm{\psi},M}\mathbf{f}(\bm x)=\bm{H_\psi}\mathbf{f}(M \bm x)$ and $\bm{H}_{\bm{\psi}}$ being the shifted Fourier  operator with  multiplier denoted by $\mathbf{m}^{\mathbf{e}}_{\bm \psi}(\bm \xi)$, where
		\begin{equation}\phantomsection\label{eq:Mult}
			\mathbf{m}^{\mathbf{e}}_{\bm \psi}(\bm \xi)=\prod_{k=1}^d\frac{W_{\phi_{+,k}}(\frac{1}{2}-{\rm{i}}\xi_k)}{W_{\phi_{-,k}}(\frac{1}{2}+{\rm i}\xi_k)},\ \ \bm{\xi}=(\xi_1, \ldots,\xi_d)\in\mathbb{R}^d.
		\end{equation}
		In fact,
		\[\mathbf{D}(\bm{H}^{-1}_{\bm{\psi},M})=\left\{\mathbf{f}\in\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M);\ \bm{\xi}=(\xi_1,\ldots,\xi_d) \mapsto\mathcal{F}^{\mathbf{e}}_{\mathbf{f}\circ M^{-1}}(\bm{\xi})\prod_{k=1}^d\frac{W_{\phi_{-,k}}(\frac{1}{2}-{\rm{i}}\xi  _k)}{W_{\phi_{+,k}}(\frac{1}{2}+{\rm{i}}\xi  _k)}\in\bmrm{L}(\mathbb{R}^d)\right\}. \]
		Under some conditions (see Proposition~\ref{prop:ratio_criterion}), $\mathbf{D}(\bm{H}^{-1}_{\bm{\psi},M})$ is the full Hilbert space and thus $\bm{H}^{-1}_{\bm{\psi},M}$ extends as a bounded operator on the entire Hilbert space. As a result, \eqref{eq:spectral_decomp} holds on $\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)$.

\phantomsection\label{thm:spectrum} Let $\bm{P}^M[\bm{\psi}] \in \mathscr{P}$ for some $M\in\mathrm{GL}_d(\mathbb R)$. 



\begin{enumerate}
\item\phantomsection\label{it:spect} For all $t\geqslant 0$,
\begin{align*}
e^{t\mathbb{R}_-}\subseteq\sigma(\bm{P}^{M}_t[\bm{\psi}]).
\end{align*}
More precisely, if $\mathbf{m}^{\mathbf{e}}_{\bm{\psi}}$ is bounded then $e^{t\mathbb{R}_-}\subseteq\sigma_{ap}(\bm{P}^{M}_t[\bm{\psi}])$, where $\mathbf{m}^{\mathbf e}_{{\bm{\psi}}}$ is defined in \eqref{eq:Mult}. If $1/\mathbf{m}^{\mathbf{e}}_{\bm\psi}$ is bounded, then $e^{t\mathbb{R}_-}\subseteq\sigma_{ap}(\widehat{\bm{P}}^M_t[\bm{\psi}])$. \vspace{.2cm}
\item\phantomsection\label{it:point_spect} If $\mathbf{m}^{\mathbf{e}}_{\bm{\psi}}\in\bmrm{L}(\mathbb{R}^d)$ then \begin{equation*}
    e^{t\mathbb{R}_-}\subseteq\sigma_p(\bm{P}^M_t[\bm{\psi}])  \mbox{  and } \sigma_r(\bm{P}^M_t[\bm{\psi}])=\emptyset
     \end{equation*}
     with, for any $\bm{q}\in\mathbb{R}_+^d$, 
 \begin{equation*}
     \bm{P}^M_t[\bm{\psi}]  \uptau_{\ln \bm{q}}\mathbf{J}^M_{\bm{\psi}}(\bm{x})= \mathbf{e}(-t\bm{q}) \: \uptau_{\ln \bm{q}}\mathbf{J}^M_{\bm{\psi}}(\bm{x})
     \end{equation*}
     where $\uptau_{\bm{q}}\mathbf{f}(\bm{x})=\mathbf{f}(\bm{x}+\bm{q})$,  $\mathbf{J}^M_{\bm{\psi}}(\bm{x})= \mathbf{J}_{\bm{\psi}}(M^{-1}{\bm{x}})$,   and \[\mathbf{J}_{\bm{\psi}}(\bm{x})=\frac{\mathbf{e}(-\bm{x}/2)}{(2\pi)^{d/2}}\int_{\mathbb{R}^d}e^{{\rm{i}}\langle\bm{x},\bm{\xi}\rangle}\mathbf{m}^{\mathbf{e}}_{\bm \psi}(\bm \xi) d\bm{\xi} \]
      where the integral is understood in the ${\mathbf{L}}^2$-sense.
    \item \phantomsection\label{it:residual_spect}If $1/\mathbf{m}^{\mathbf e}_{\bm\psi}\in\bmrm{L}(\mathbb{R}^d)$ then
         \begin{equation*}
    e^{t\mathbb{R}_-}\subseteq\sigma_r(\bm{P}^M_t[\bm{\psi}]) \mbox{ and } \sigma_p(\bm{P}^M_t[\bm{\psi}])=\emptyset
     \end{equation*}
     with,  for any $\bm{q}\in\mathbb{R}_+^d$, $t>0$ and $\mathbf{f}\in\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)$,
     \begin{equation*}
     \left\langle \bm{P}^M_t[\bm{\psi}] \mathbf{f},\uptau_{\ln \bm{q}}\mathbf{J}^M_{\overline{\bm{\psi}}}\right\rangle_{\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)}   = \mathbf{e}(-t\bm{q}) \left\langle \mathbf{f},\uptau_{\ln \bm{q}}\mathbf{J}^M_{\overline{\bm{\psi}}}\right\rangle_{\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)}.
     \end{equation*}
\item \phantomsection\label{it:cont_spect} If $\mathbf{m}^{\mathbf e}_{\bm\psi}$ is both bounded from above and below then \begin{equation} \phantomsection\label{eq:contSpec}
    \sigma(\bm{P}^M_t[\bm{\psi}])=\sigma_c(\bm{P}^M_t[\bm{\psi}])=e^{t\mathbb{R}_-}.
     \end{equation}
     In particular, when $\bm{P}^M_t[\bm{\psi}]$ is self-adjoint, i.e.~$\bm{\psi}=\overline{\bm{\psi}}$, then \eqref{eq:contSpec} holds. 
\end{enumerate}

 For the point and residual spectrum, there are plenty of natural examples, and,  we detail some of them in Sections \ref{ex:spectrally_neg} and \ref{ex:two_sided}. More generally, for any $\phi\in\mathbf{B}$, defining
\begin{align}\phantomsection\label{eq:Thetas}
 \underline{\Theta}_\phi=\liminf_{|\xi|\to\infty}\Theta_\phi(|\xi|) \mbox{ and } \overline{\Theta}_\phi=\limsup_{|\xi|\to\infty}\Theta_\phi(|\xi|)
\end{align}
where $\Theta_\phi(|\xi|)=\frac{\int_{1/2}^\infty\ln\left(\frac{|\phi(a+\mathrm{i}|\xi|)|}{\phi(a)}\right)\,da}{|\xi|}$, one easily deduces from \cite[Theorem 6.2(1)]{patiesavov}, that,  for any $\xi \in \mathbb{R}$,
\begin{equation}\phantomsection\label{eq:ration-gene}
		\left|\frac{W_{\phi_+}\left(\frac{1}{2}+{\rm{i}}\xi\right)   }{W_{\phi_-}\left(\frac{1}{2}+{\rm{i}}\xi\right)   }\right|\asymp\frac{\sqrt{|\phi_-\left(\frac{1}{2}+{\rm{i}}\xi\right) |}}{\sqrt{|\phi_+\left(\frac{1}{2}+{\rm{i}}\xi\right)   |}}e^{-|\xi|(\Theta_{\phi_+}(|\xi|)-\Theta_{\phi_-}(|\xi|))}.
	\end{equation} 
Thus, if $\underline{\Theta}_{\phi_+}>\overline{\Theta}_{\phi_-}$ (resp.~$\underline{\Theta}_{\phi_-}>\overline{\Theta}_{\phi_+}$), then ${P}[\psi]$ has point spectrum (resp.~has residual spectrum). For a proof of the last two statements and also sufficient conditions for both point and residual spectrum  in the case $\underline{\Theta}_{\phi_+}=\overline{\Theta}_{\phi_-}$, we refer to Proposition~\ref{prop:ratio_criterion}. In Section \ref{sec:cont_spect_ex}, we  provide examples of $\psi'$s for which ${P}[\psi]$ is non-self-adjoint and has continuous spectrum. However, in general, though we have always $e^{t\mathbb{R}_-}\subseteq\sigma(\bm{P}^M_t[\bm{\psi}])$, the weak similarity relation does not allow to check the reverse inclusion.

We start by introducing the following subset of $\bmrm{L}(\mathbb R^d,\mathbf{e})$
\begin{equation}
		\bm{\mathcal{E}}=\bigotimes_{k=1}^d\mathcal{E} \mbox{ with }  \mathcal{E}=\mathrm{Span}\{\mathfrak{h}_{\epsilon,\beta};\: \epsilon,\beta>0\}
\end{equation}
where $\mathfrak{h}_{\epsilon,\beta}: \mathbb{R} \to \mathbb{R}_+$ is defined by $\mathfrak{h}_{\epsilon,\beta}(x)=e^{-(\frac{1}{2}+\epsilon)x}e^{-\beta e^{-x}}$, and $\otimes$ stands for the tensor product of the univariate functions.

\phantomsection\label{thm:core_multi_d}
Let $M\in\mathrm{GL}_d(\mathbb R)$.
\begin{enumerate}
\item\phantomsection\label{it:feller_semigroup} We have \[ \mathscr{P}_M \subset \mathcal{C}^+_0(\bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)).\] More specifically, $\bm{P}^M[\bm{\psi}]$,  when restricted to $\mathbf{C}_0(\mathbb{R}^d) \cap \bmrm{L}(\mathbb{R}^d,{\mathbf{e}}_M)$, extends to the semigroup of the Feller process on $\mathbb{R}^d$ defined, for any $t\geqslant0$, as $\bm{Y}_t = M \bm{X}_t,$ where $\bm{X}_t=(\ln X^{(1)}_t, \ldots,\ln X^{(d)}_t)$, the stochastic processes $(X^{(k)}_t)_{t\geqslant0}, k=1,\ldots,d,$ are mutually independent  and each of them is a positive self-similar  Feller process on $(0,\infty)$, see Section \ref{sec:lamp} for more details on these processes.
	\item\phantomsection\label{it:core} If $\bm{\psi}$ satisfies the conditions \eqref{cond:finite_mean} and \eqref{eq:schwarz_decay}, then $\bm{\mathcal{E}}^M_{\bm \psi}:=\bm{H}^M_{\bm\psi}(\bm{\mathcal{E}})$ is a core for $\bm{A}_{\mathtt 2}[\bm \psi]$, and its restriction on $\bm{\mathcal{E}}^M_{\bm \psi}$  coincides with $\bm{A}^M[\bm\psi]$ defined in \eqref{eq:fourier_int}.
\end{enumerate}

