\phantomsection\label{prop:contour} Let $f\in\mathbf{A}_{[0,\gamma]}$ for some $\gamma>0$ and there exists $1\leqslant p \leqslant \infty$ such that\hpt{R6}{, for $p<\infty$,
\begin{align*}

\sup\limits_{b\in [0,\gamma]}\left(\int_{\mathbb R}\left|f(x+{\rm{i}}b)\right|^p dx\right)^{\frac{1}{p}}<\infty,
\end{align*}
(resp.~ the supremum norm is finite for $p=\infty$).}
Then, one can choose a subsequence $(n_j)_{j\geqslant 1}$ of natural numbers such that for any $0\leqslant b\leqslant\gamma$,
\begin{align*}
\lim\limits_{j\to\infty}\int_{-n_j}^{n_j} [f(x+\mathrm{i} b)-f(x)]dx=0.
\end{align*}
In particular, when $p=1$, $\int_\mathbb{R} f(x)dx=\int_{\mathbb R} f(x+\mathrm{i} b)dx$ for all $0\leqslant b\leqslant \gamma$, and when $p=\infty$, $\lim\limits_{n\to\infty}\int_{-n}^n [f(x+\mathrm{i} b)-f(x)]dx=0$ for all $0\leqslant b\leqslant\gamma$.

	Let us first assume that $1\leqslant p<\infty$. From the analyticity of $f$ in the strip $\mathbb{S}_{[0,\gamma]}$ and applying the Cauchy integral formula, for any $x>0$ and $0<b\leqslant\gamma$ we have
	\begin{align*}
		\int_{R^b_x} f(z) dz=0
	\end{align*}
where $R^b_x$ is the rectangle formed by the points $-x,x,x+\mathrm{i} b, -x+\mathrm{i} b$. Let us estimate the integrals on the vertical lines of $R^b_x$. By H\"older's inequality, we have
\begin{align*}
		\left(\int_{0}^b |f(\pm x+\mathrm{i} y)|dy\right)^p\leqslant\left(\int_{0}^{\gamma} |f(\pm x+\mathrm{i} y)|dy\right)^p\leqslant \gamma^{\frac{p}{q}}\int_0^\gamma |f(\pm x+\mathrm{i} y)|^p dy
\end{align*}
where $\frac{1}{p}+\frac{1}{q}=1$ with $q=\infty$ when $p=1$. Applying Fubini's theorem combined with the assumption of the lemma, we get
\begin{align*}
	\int_\mathbb{R}\left(\int_{0}^{\gamma} |f(x+\mathrm{i} y)|dy\right)^p dx\leqslant\gamma^{\frac{p}{q}}\int_0^\gamma\int_{\mathbb R} |f(x+\mathrm{i} y)|^p dx\,dy<\infty
\end{align*}
which implies that there exists a subsequence $(n_j)_{j\geqslant 1}$ of natural numbers such that
\begin{align*}
\lim_{j\to\infty}\int_{0}^{\gamma} |f(\pm n_j+\mathrm{i} y)|dy=0.
\end{align*}
As a result, for any $0\leqslant b\leqslant \gamma$,
	$\lim\limits_{j\to\infty}\left(\int_{-n_j}^{n_j} [f(x+\mathrm{i} b)-f(x)]-\int_{R^b_{n_j}} f(z)dz\right)=0$, which proves the lemma. When $p=\infty$, for any $0<b\leqslant\gamma$, the integral on the vertical lines of $R^b_x$ goes to $0$ as $x\to\infty$. This completes the proof of the lemma for all $1\leqslant p\leqslant\infty$.

\begin{align*}
		\left(\int_{0}^b |f(\pm x+\mathrm{i} y)|dy\right)^p\leqslant\left(\int_{0}^{\gamma} |f(\pm x+\mathrm{i} y)|dy\right)^p\leqslant \gamma^{\frac{p}{q}}\int_0^\gamma |f(\pm x+\mathrm{i} y)|^p dy
\end{align*}

