    -\mathbbm{a}(\bm{x},D)f(x)=-(2\pi)^{-\frac{d}{2}}\int_{\mathbb{R}^d}e^{\mathrm{i}\langle\bm{\xi},\bm{x}\rangle}\mathcal{F}_{\mathbf{f}}(\bm{\xi})\mathbbm{a}(\bm{x},\bm{\xi})\,d\bm{\xi}~, \  \  \mathbf{f}\in\mathbf{S}(\mathbb{R}^d),
