\phantomsection\label{ss:fourier_mult}
We recall that an operator $\Lambda:\bmrm{L}(\mathbb{R},e)\to\bmrm{L}(\mathbb{R},e)$ is called a shifted Fourier multiplier operator if there exists a measurable function $m^e_\Lambda:\mathbb{R}\to\mathbb{C}$ such that, for all $\xi\in\mathbb{R}$,
\begin{align*}
	\mathcal{F}^{e}_{\Lambda f}(\xi)=m^e_\Lambda(\xi)\mathcal{F}^{e}_f(\xi)
\end{align*}
for all $f\in\bmrm{L}(\mathbb{R},e)$ with $m^e_\Lambda\mathcal{F}^{e}_{\!f}\in\bmrm{L}(\mathbb{R})$.

\phantomsection\label{multiplier_result}
\hpt{R11}{Consider $\Lambda\in\mathscr{M}$} such that $m_\Lambda$ extends continuously on $\mathbb R$. Let $f\in\mathbf{D}(\Lambda)$ be such that for some $\frac{1}{2}\leqslant\gamma\leqslant 1$,
\begin{enumerate}[(i)]
\item $\mathcal{F}_f\in\mathbf{A}_{[0,\gamma]}$ and $\mathcal{F}_f(\cdot+\mathrm{i} b)\in\bmrm{L}(\mathbb R)$ for all $0\leqslant b\leqslant \gamma$

\item \phantomsection\label{it:sup}$\sup\limits_{b\in [0,\gamma]}\int_{\mathbb{R}}|m_{\Lambda}(\xi+{\rm{i}}b)\mathcal{F}_{f}(\xi+{\rm{i}}b)|^2\,d\xi<\infty$.
\end{enumerate}
Then, $\Lambda f\in\mathbf{L}^2(\mathbb R, e^{2bx})$ for any $0\leqslant b\leqslant\gamma$, and for all $\xi\in\mathbb R$,
\begin{align}\phantomsection\label{eq:fourier_b}
	\mathcal{F}_{\Lambda f}(\xi+\mathrm{i} b)=m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b).

\end{align}

 We first note that condition~\eqref{it:sup} ensures that for any $0\leqslant b\leqslant \gamma$, there exists $g_b\in\bmrm{L}(\mathbb R)$ such that $\mathcal{F}_{\! g_b}(\xi)=m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b)$ for all $\xi\in\mathbb R$. Now, from the standard theory of Fourier transform, it is known that for any $0\leqslant b\leqslant \gamma$,
\begin{align*}
	g_b(x)=\lim_{n\to\infty}\frac{1}{\sqrt{2\pi}}\int_{-n}^n m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b) e^{\mathrm{i}\xi x} d\xi
\end{align*}
where the above convergence holds in $\bmrm{L}(\mathbb R)$. Now, for each $x\in\mathbb R$, since the integrand above satisfies the condition of Lemma~\ref{prop:contour} with $p=2$, we can therefore choose a subsequence $(n_j)_{j\geqslant 1}$ such that for all $x\in\mathbb R$ and $0\leqslant b\leqslant\gamma$,
\begin{align*}
	\frac{1}{\sqrt{2\pi}}\int_{-n_j}^{n_j}m_\Lambda(\xi)\mathcal{F}_f(\xi) e^{\mathrm{i}\xi x}d\xi-\frac{1}{\sqrt{2\pi}}\int_{-n_j}^{n_j} m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b) e^{\mathrm{i}\xi x} e^{-bx} d\xi\to 0
\end{align*}
as $j\to\infty$. Note that the first integrand above converges to $g_0(x)$ and the second integral converges to $e^{-bx}g_b(x)$ in $\bmrm{L}(\mathbb R)$, which implies that $g_b(x)=e^{bx} g_0(x)$ for all $0\leqslant b\leqslant \gamma$, in particular when $b=\frac{1}{2}$. Now, from the definition of $\Lambda f$, it is clear that $\Lambda f(x)=e^{-\frac{x}{2}}g_{\frac{1}{2}}(x)=g_0(x)$. The above computation shows that $g_0\in\bmrm{L}(\mathbb R, e^{2bx})$ for all $0\leqslant b\leqslant \gamma$, which proves the first statement of the result. By means of Cauchy-Schwarz inequality, for any $0<b<\gamma$ we have
\begin{align*}
	\left(\int_{-\infty}^0 |g_0(x)|e^{bx} dx\right)^2&\leqslant\int_{-\infty}^0 |g_0(x)|^2dx\int_{-\infty}^0 e^{2bx}dx<\infty \\
	\left(\int_{0}^\infty |g_0(x)| e^{bx}dx\right)^2&\leqslant\int_{0}^\infty |g_0(x)|^2 e^{2\gamma x}dx\int_0^\infty e^{-2(\gamma-b)x} dx<\infty
\end{align*}
which shows that $\Lambda f=g_0\in \mathbf{L}^1(\mathbb R, e^{bx})$ for all $0<b<\gamma$. Hence, for any $0<b<\gamma$ one has
\begin{align*}
	\mathcal{F}_{\Lambda f}(\xi+\mathrm{i} b)=\frac{1}{\sqrt{2\pi}}\int_{\mathbb R} g_0(x)e^{bx}e^{-\mathrm{i} \xi x} dx=\frac{1}{\sqrt{2\pi}}\int_{\mathbb R} g_b(x)e^{-\mathrm{i} \xi x} dx=m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b).
\end{align*}
Since $\Lambda f\in\bmrm{L}(\mathbb R)\cap \bmrm{L}(\mathbb R, e^{2\gamma x})$ and the right-hand side of the above equation extends continuously to the boundary of $\mathbb{S}_{(0,\gamma)}$, \eqref{eq:fourier_b} follows for all $0\leqslant b\leqslant \gamma$.

\begin{align*}
	g_b(x)=\lim_{n\to\infty}\frac{1}{\sqrt{2\pi}}\int_{-n}^n m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b) e^{\mathrm{i}\xi x} d\xi
\end{align*}

\begin{align*}
	\frac{1}{\sqrt{2\pi}}\int_{-n_j}^{n_j}m_\Lambda(\xi)\mathcal{F}_f(\xi) e^{\mathrm{i}\xi x}d\xi-\frac{1}{\sqrt{2\pi}}\int_{-n_j}^{n_j} m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b) e^{\mathrm{i}\xi x} e^{-bx} d\xi\to 0
\end{align*}

\begin{align*}
	\left(\int_{-\infty}^0 |g_0(x)|e^{bx} dx\right)^2&\leqslant\int_{-\infty}^0 |g_0(x)|^2dx\int_{-\infty}^0 e^{2bx}dx<\infty \\
	\left(\int_{0}^\infty |g_0(x)| e^{bx}dx\right)^2&\leqslant\int_{0}^\infty |g_0(x)|^2 e^{2\gamma x}dx\int_0^\infty e^{-2(\gamma-b)x} dx<\infty
\end{align*}

\begin{align*}
	\mathcal{F}_{\Lambda f}(\xi+\mathrm{i} b)=\frac{1}{\sqrt{2\pi}}\int_{\mathbb R} g_0(x)e^{bx}e^{-\mathrm{i} \xi x} dx=\frac{1}{\sqrt{2\pi}}\int_{\mathbb R} g_b(x)e^{-\mathrm{i} \xi x} dx=m_{\Lambda}(\xi+\mathrm{i} b)\mathcal{F}_f(\xi+\mathrm{i} b).
\end{align*}

\phantomsection\label{dense_range_intertwining}
Any $(\Lambda,\mathbf{D}(\Lambda))\in\mathscr{M}$ is densely defined with dense range in $\bmrm{L}(\mathbb{R},e)$ 
 and $\widehat{\mathcal F}^e_{\!\mathbf{C}^\infty_c(\mathbb{R})}$ is a core.

Let $f\in\mathbf{D}(\Lambda)$ be such that  $\mathcal{F}^{e} _{f}(\xi)\neq 0$ a.e.. Then, for any $a,\xi\in\mathbb{R}$,  \[ \mathcal{F}^{e}_{\uptau_a\Lambda f}(\xi)=e^{{\rm i}a-\frac{a}{2}}m_{\Lambda}\left(\xi+{\rm{i}}/2\right)\mathcal{F}^{e}_f (\xi)=m_{\Lambda}\left(\xi+{\rm{i}}/2\right)\mathcal{F}^{e}_{\uptau_a f}(\xi)=\mathcal{F}^{e}_{\Lambda\uptau_a f}(\xi),\] that is $\uptau_a\Lambda f\in\operatorname{Range}(\Lambda)$. An application of Wiener's Tauberian theorem yields that the set $\mathrm{Span}\{\uptau_a\Lambda f; \ a\in\mathbb{R}\}$ is dense in $\bmrm{L}(\mathbb{R},e)$. Next, we observe  that
\begin{align}
\mathbf{D}(\Lambda)=\left\{f\in\bmrm{L}(\mathbb{R},e); \: \mathcal{F}^{e} _{f}\in\bmrm{L}\left(\mathbb{R}, \left(1+\left|m_\Lambda\left(\xi+{\rm{i}}/2\right)\right|^2\right)\,d\xi\right)\right\}.
\end{align}
Since the function $1+\left| m_\Lambda\left(\cdot+\mathrm{i}/2\right)\right|^2$ is locally integrable, the corresponding weighted $\mathrm{L}^2$-space has $\mathbf{C}^\infty_c(\mathbb{R})$ as a dense subset. Also, the graph norm of $\Lambda$, which is given by $\|f\|_{\Lambda}:=\|f\|_{\bmrm{L}(\mathbb{R},e)}+\|\Lambda f\|_{\bmrm{L}(\mathbb{R},e)}$, is equivalent to the norm of $\bmrm{L}\left(\mathbb{R}, \left(1+\left|m_\Lambda\left(\xi+\mathrm{i}/2\right)\right|^2\right)\,d\xi\right)$. Thus, $\mathcal{F}^{e}_{\mathbf{C}^\infty_c(\mathbb{R})}$  is dense in $\mathbf{D}(\Lambda)$ with respect to the graph norm $\|\cdot\|_{\Lambda}$ and hence is a core of $(\Lambda,\mathbf{D}(\Lambda)).$

Let $\mathscr{M}_e$ be the class of operators in $\mathscr{M}$ with the following additional property
\begin{align}\phantomsection\label{eq:mult_strip}
\mbox{For all} \ (\Lambda,\mathbf{D}(\Lambda))\in\mathscr{M}_e, \ \left|m_{\Lambda}\left(\xi+{\rm{i}}/2\right)\right|\leqslant Ce^{k|\xi|}, \  \mbox{ for all } \xi\in\mathbb R,
\end{align}
where $C,k$ are positive constants depending on $\Lambda$ but does not depend on $\xi$.

If $\hpt{R16}{A\Lambda=\Lambda B}$ on $\mathbf{D}(\Lambda)$, then by injectivity of $\Lambda$, we have $B\Lambda^{-1}=\Lambda^{-1} A$ on $\operatorname{Range}(\Lambda)=\mathbf{D}(\Lambda^{-1})$. To prove the transitivity property, we consider  $A,B,C\in\mathscr{B}(\bmrm{L}(\mathbb{R},e))$ such that $A\Lambda_1=\Lambda_1 B$ on $\mathbf{D}(\Lambda_1)$ and $B\Lambda_2=\Lambda_2 C$ on $\mathbf{D}(\Lambda_2)$. Then, we already have $A\Lambda_1\Lambda_2=\Lambda_1\Lambda_2 B$ on $\{f\in\bmrm{L}(\mathbb{R},e); \: f\in\mathbf{D}(\Lambda_2), \ \Lambda_2 f\in\mathbf{D}(\Lambda_1)\}$.
By Proposition \ref{dense_range_intertwining}, the set $\widehat{\mathcal F}^e_{\!\mathbf{C}^\infty_c(\mathbb{R})}$ is a core for $\Lambda_1, \Lambda_2$, and $\overline{\Lambda_1\Lambda_2}$, where
\begin{align*}
	\mathbf{D}(\overline{\Lambda_1\Lambda_2})=\left\{f\in\bmrm{L}(\mathbb{R},e); \: \xi \mapsto m_{\Lambda_1}\left(\xi+{\rm{i}}/2\right)m_{\Lambda_2}\left(\xi+{\rm{i}}/2\right)\mathcal{F}^{e} _{f}(\xi)\in\bmrm{L}(\mathbb{R},e)\right\}.
\end{align*}
 Moreover, $\widehat{\mathcal F}^e_{\!\mathbf{C}^\infty_c(\mathbb{R})}\subset\{f\in\bmrm{L}(\mathbb{R},e); \: f\in\mathbf{D}(\Lambda_2), \ \Lambda_2 f\in\mathbf{D}(\Lambda_1)\}$. Hence, the identity $A\overline{\Lambda_1\Lambda_2}=\overline{\Lambda_1\Lambda_2} B$ holds on $\mathbf{D}(\overline{\Lambda_1\Lambda_2})$ by a density argument.

\cite[Theorem 1.3]{Pazy}\phantomsection\label{lem:weak=strong}
Let $(P_t)_{t\geqslant0}$ be a $\mathcal{C}_0$-contraction semigroup 
of bounded operators on a Banach space ${\bf{Y}}$. Let $(\tilde{A},\mathbf{D}(\tilde{A}))$ and $(A,\mathbf{D}(A))$ denote the weak and strong generator of this semigroup respectively. Then, $(\tilde{A},\mathbf{D}(\tilde{A}))=(A,\mathbf{D}(A))$.

Consider any $f\in\hptg{C28}{\mathbf{D}(A_\mathtt{F})}\cap\bmrm{L}(\mathbb R,\varepsilon)$ such that $A_\mathtt{F}f\in\bmrm{L}(\mathbb{R},\varepsilon)$ and $g\in\bmrm{L}(\mathbb{R},\varepsilon)$. Then, we know that, for all $t\geqslant 0$,
\hpt{R20}{$P_t$ is a contraction on $\mathbf{C}_0(\mathbb{R})\cap \bmrm{L}(\mathbb{R},\varepsilon)$
with respect to the $\bmrm{L}(\mathbb{R},\varepsilon)$ norm}, and,

\begin{equation}\phantomsection\label{weak}
\begin{aligned}
 \left\langle(P^{(\mathtt{2})}_tf-f)/t,g\right\rangle_{\bmrm{L}(\mathbb{R},\varepsilon)}=\left\langle (P_tf-f)/t,g\right\rangle_{\bmrm{L}(\mathbb{R},\varepsilon)}.
\end{aligned}
\end{equation}
Since $A_\mathtt{F}$ is the generator of the Feller semigroup $(P_t)_{t\geqslant 0}$, we have
\begin{align*}
\lim_{t\to 0}\left\|(P_t f-f)/t-A_\mathtt{F} f\right\|_{\infty}= 0
\end{align*}
where $\|\cdot\|_{\infty}$ stands for the supremum norm in $\mathbf{C}_0(\mathbb R)$. Since $A_\mathtt{F} f\in\bmrm{L}(\mathbb{R},\varepsilon)$, we observe that for any $t>0$,
\begin{equation*}
\left\|\frac{P_t f-f}{t}\right\|_{\hpt{R21}{\bmrm{L}(\mathbb{R},\varepsilon)}}=\frac{1}{t}\left\|\int_0^t P_s A_\mathtt{F} fds\right\|_{\bmrm{L}(\mathbb{R},\varepsilon)}\leqslant\frac{1}{t}\int_0^t \|P_s A_\mathtt{F} f\|_{\bmrm{L}(\mathbb{R},\varepsilon)}ds\leqslant \|A_\mathtt{F} f\|_{\bmrm{L}(\mathbb{R},\varepsilon)}.
\end{equation*}
Now, \eqref{weak} implies that if $g\in\mathbf{L}^1(\mathbb{R},\varepsilon)\ \cap\ \mathbf{L}^2(\mathbb{R},\varepsilon)$, then
$
\lim_{t\to 0}\left\langle\frac{P_t f-f}{t},g\right\rangle_{\bmrm{L}(\mathbb{R},\varepsilon)}=\langle A_\mathtt{F} f,g\rangle_{\bmrm{L}(\mathbb{R},\varepsilon)}.
$
On the other hand, since $\{(P_tf-f)/t ; \: t>0\}$ is bounded in $\mathbf{L}^2(\mathbb R,\varepsilon)$, it is therefore weakly compact in $\mathbf{L}^2(\mathbb R,\varepsilon)$. Let $f^*$ be a weak subsequential limit of $(P_tf-f)/t$ as $t\to 0$. Then, by \eqref{weak} and the discussion above, we have
$
\langle f^*,g\rangle_{\bmrm{L}(\mathbb{R},\varepsilon)}=\langle f,g\rangle_{\bmrm{L}(\mathbb{R},\varepsilon)} \ \mbox{ for all }  \ g\in\mathbf{L}^1(\mathbb{R},\varepsilon)\cap\bmrm{L}(\mathbb{R},\varepsilon).
$
Since $\mathbf{L}^1(\mathbb{R},\varepsilon)\cap\bmrm{L}(\mathbb{R},\varepsilon)$ is dense in $\bmrm{L}(\mathbb{R},\varepsilon)$, we infer that
$\frac{P^{(2)}_tf-f}{t}\to A_\mathtt{F} f$ weakly for all $f\in\mathbf{D}(A_\mathtt{F})\cap\bmrm{L}(\mathbb{R},\varepsilon)$, as $t\to 0$. Finally, invoking Lemma~\ref{lem:weak=strong}, we conclude that $A_\mathtt{F} f$ is also the strong limit of $(P^{(\mathtt{2})}_t f-f)/t$, which completes  the proof.

