W_+(z)=\frac{W_{\phi_+}(-{\rm i} z)}{\Gamma({-\rm i}z)}, &  z\in\mathbb{S}_{(0,\infty)} \vspace{.3 cm} \\
W_-(z)=\frac{\Gamma(1+{\rm i}z+\beta)}{W_{\phi_-}(1+{\rm i}z)}, &  \mbox{for any $\beta>0$ and $z\in\mathbb{S}_{(-\infty,1)}$}.
\end{cases}
\end{align*}

\begin{align*}
W_+(z+{\rm i})&=\frac{W_{\phi_+}(-{\rm i}z+1)}{\Gamma(-{\rm i}z+1)}=\frac{\phi_+(-{\rm i}z)}{-{\rm i}z}\frac{W_{\phi_+}(-{\rm i}z)}{\Gamma(-{\rm i}z)}=\frac{\phi_+(-{\rm i}z)}{-{\rm i}z}W_+(z)
\end{align*}

\phantomsection\label{lem:bound_bernstein}
  		For any $\phi\in\mathbf{B}$, $a,b\geqslant 0$, and for all $\xi\in\mathbb{R}$ one has
  		\begin{align}
  			|\phi(a+\mathrm{i}\xi)-\phi(b+\mathrm{i}\xi)|\leqslant \phi(|a-b|)-\phi(0). \notag
  		\end{align}
  		Thus, for any $a,b>0$, as $|\xi|\to\infty$, $\phi(a+\mathrm{i}\xi)\asymp\phi(b+\mathrm{i}\xi)$.

Let $\phi$ be of the form \eqref{eq:phi_def}. Then, for any $a,b\geqslant 0$ and $\xi\in\mathbb{R}$, we can write
\begin{align*}
	\phi(a+\mathrm{i}\xi)-\phi(b+\mathrm{i}\xi)=\mathtt{d}(a-b)+\int_{\mathbb{R}}\left(e^{-(a+\mathrm{i}\xi)y}-e^{-(b+\mathrm{i}\xi)y}\right)\nu(dy)
\end{align*}
Now, let us assume that $a<b$. Applying triangle inequality to the right-hand side of the above equality, we obtain
\begin{align*}
	|\phi(a+\mathrm{i}\xi)-\phi(b+\mathrm{i}\xi)|\leqslant \mathtt{d}(b-a)+\int_{\mathbb{R}} (1-e^{-(b-a)y}) e^{-ay}\nu(dy)\leqslant\phi(b-a)-\phi(0).
\end{align*}
Since $|\phi(a+\mathrm{i}\xi)|\geqslant \phi(a)>0$ for any $a>0$, from the above inequality we obtain that
\begin{align*}
	\left|\frac{\phi(a+\mathrm{i}\xi)}{\phi(b+\mathrm{i}\xi)}-1\right|\leqslant\frac{\phi(|a-b|)-\phi(0)}{\phi(b)}, \ \ \left|\frac{\phi(b+\mathrm{i}\xi)}{\phi(a+\mathrm{i}\xi)}-1\right|\leqslant \frac{\phi(|a-b|)-\phi(0)}{\phi(a)}
\end{align*}
which completes the proof of the lemma.

	From the definition of the function $W^{(\beta)}_\psi$ and exploiting the recursion in \eqref{eq:fneq} along with the representation in \eqref{eq:bernstein_gamma_bound}, it suffices to prove that there exist $u,C>0$ such that
	\begin{align}\phantomsection\label{eq:phi_bound}
		\left|\frac{z}{\phi_+(z)}\right|\leqslant  C|z|^{u} \quad \text{for all $z\in \mathbb{C}_{[0,1]}$},
	\end{align}
	where we recall that $z\in\mathbb{C}_{[0,1]}=\{z\in\mathbb{C};\ \textrm{Re}(z)\in [0,1]\}$. Now, for any $a>0$ and $\xi\in\mathbb R$, applying Lemma~\ref{lem:bound_bernstein} we get
	\begin{align*}
		\left|\frac{\phi_+(\mathrm{i}\xi)}{\phi_+(a+\mathrm{i}\xi)}-1\right|\leqslant \frac{\phi_+(a)-\phi_+(0)}{|\phi_+(a+\mathrm{i}\xi)|}\leqslant\frac{\phi_+(a)-\phi_+(0)}{\phi_+(a)}\leqslant 1,
	\end{align*}
which shows that $|\phi_+(a+\mathrm{i}\xi)|\geqslant\frac{1}{2}|\phi_+(\mathrm{i}\xi)|$ for all $a>0, \xi\in\mathbb R$. Therefore, invoking \eqref{N_+} it follows that $\liminf_{|\xi|\to\infty} |\xi|^\kappa|\phi_+(a+\mathrm{i}\xi)|>0$, uniformly with respect to $a\in [0,1]$. Since by \eqref{eq:phi_derivative}, the mapping  $z\mapsto |\frac{z}{\phi_+(z)}|$ is bounded near $0$, \eqref{eq:phi_bound} holds with $u=\kappa+1$.

By Stirling asymptotic formula for the gamma function and recalling from \cite[Proposition~3.1(4)]{patie2018} that $\phi_-(-\mathrm{i}\xi)=-\mathrm{i}\mathtt{d}_-\xi+\mathrm{o}(|\xi|)$,
we get
\begin{align}\phantomsection\label{eq:gamma_phi_ratio}
\frac{\Gamma(\beta-\mathrm{i}\xi)\phi_-(-\mathrm{i}\xi)}{\Gamma(1+\mathrm{i}\xi)}=\mathrm{O}(|\xi|^\beta).
\end{align}

\phantomsection\label{thm:intertwining_pdo}
\begin{enumerate}[(1)]
\item\phantomsection\label{main_thm_1:it:0a} Let $\psi_0(\xi)=\xi^2, \: \xi \in \mathbb{R}$, then the closure of the operator $(A_{\mathtt{PDO}}[\psi_0],\mathbf{C}^\infty_c(\mathbb R))$ in $\bmrm{L}(\mathbb{R},e)$ generates the log-squared Bessel semigroup $Q$ on $\bmrm{L}(\mathbb{R},e)$.
\item\phantomsection\label{main_thm_1:it:1a} For any $\psi\in\mathbf{N}_b(\mathbb R)$, the shifted Fourier multiplier operator $\Lambda_\psi\in\mathscr{M}_e$, where $m_{\Lambda_\psi}(z)=\frac{W_{\phi_+}(-{\rm{i}}z   )}{W_{\phi_-}(1+{\rm{i}}z)   }\frac{\Gamma(1+{\rm{i}}z)   }{\Gamma(-{\rm{i}}z   )}$ for all $z\in\mathbb{S}_{(0,1)}$. In particular, when $\psi\in\mathbf{N}_+(\mathbb R)$, $\Lambda_\psi\in\mathscr{B}(\bmrm{L}(\mathbb{R},e))$.
\item\phantomsection\label{main_thm_1:it:1b} For any $\psi\in\mathbf{N}_b(\mathbb R)$, we have $A_\mathtt{PDO}[\psi]\in\mathrm{WS}(A_\mathtt{PDO}[\psi_0])$. More specifically, recalling that $\mathcal{D}(\mathbb R) = \{f\in \bmrm{L}(\mathbb{R},e);\: \mathcal{F}_f \textrm{ is entire and satisfies \eqref{eq:udec}}\}$,  we have $\mathcal{D}(\mathbb R)$ is dense in $\bmrm{L}(\mathbb{R},e)$, and,
\begin{align}\phantomsection\label{eq:intertwining_pdo_0_D}
A_\mathtt{PDO}[\psi]\Lambda_\psi =\Lambda_\psi A_\mathtt{PDO}[\psi_0]\ \mbox{ on } \ \mathcal{D}(\mathbb{R}).
\end{align}
In particular, if $\psi\in\mathbf{N}_+(\mathbb R)$ then \eqref{eq:intertwining_pdo_0_D} holds on $\mathbf{C}^\infty_c(\mathbb R)$.
\item \phantomsection\label{main_thm_1:it:1bc} If $\psi\in\mathbf{N}_+(\mathbb R)$ then the closure of the operator $(A_\mathtt{PDO}[\psi],\Lambda_\psi(\mathbf{C}^\infty_c(\mathbb R)))$ in $\bmrm{L}(\mathbb{R},e)$ generates the semigroup $P[\psi]$ on $\bmrm{L}(\mathbb{R},e)$. Therefore, in this case, $\Lambda_\psi(\mathbf{C}^\infty_c(\mathbb R))$ is a core for $A_\mathtt{2}[\psi]$. In general, for any $\psi\in\mathbf{N}_b(\mathbb R)$, we have
\begin{align}\phantomsection\label{eq:A_2=A_PDO}
	A_\mathtt{2}[\psi]=A_{\mathtt{PDO}}[\psi] \ \ \text{on} \ \ \Lambda_\psi(\mathcal{D}(\mathbb R))
\end{align}
and $\Lambda_\psi(\mathcal{D}(\mathbb R))$ is dense in $\bmrm{L}(\mathbb{R},e)$.

\item \phantomsection\label{main_thm_1:it:1d} For any $\psi\in\mathbf{N}_b(\mathbb R)$ and  $t\geqslant 0$, we have
\begin{align}\phantomsection\label{eq:bdd_intertwining}
P_t[\psi]\Lambda_\psi=\Lambda_\psi Q_t \ \mbox{ on } \ \mathbf{D}(\Lambda_\psi).
\end{align}
If $H_\psi$ is the shifted Fourier multiplier operator with $m_{\psi}(z):=m_{H_\psi}(z)=\frac{W_{\phi_+}(-{\rm{i}}z)}{W_{\phi_-}(1+{\rm{i}}z)}$, then $(H_\psi,\mathbf{D}(H_\psi))\in\mathscr{M}_e$, and, for all $t\geqslant 0$, we have
\begin{align}\phantomsection\label{eq:spect_decomp}
	P_t[\psi] =H_\psi e_tH^{-1}_\psi \ \mbox{ on  } \ \hptg{C37}{\mathbf{D}(H^{-1}_\psi)}
\end{align}
where  $(e_t)_{t\geqslant 0}$ denotes the multiplication semigroup on $\bmrm{L}(\mathbb{R},e)$, i.e.~ $\hptg{C36}{e_t f(x)=e^{-te^{-x}}f(x)}$. Note that $H^{-1}_\psi=\widehat{H}_{\overline{\psi}}$ as they correspond to the same multiplier.
\end{enumerate}

\phantomsection\label{prop:core_ido} Let $\psi\in\mathbf{N}_b(\mathbb{R})$ and denote by $A_\mathtt{2}[\psi]$ the $\bmrm{L}(\mathbb{R},e)$-generator of $P[\psi]$.
\item \phantomsection\label{it:main_2}
\begin{enumerate}[(1)]
\item \phantomsection\label{it:2d_new} If $\psi(\xi)=-\mathrm{i}\mathtt{d}\xi$ for some $\mathtt{d}>0$, then $\mathbf{C}^\infty_c(\mathbb{R})$ is a core for $A_\mathtt{2}[\psi]$. Otherwise, let us assume that
\begin{align}\phantomsection\label{eq:mpsi_bound}
	\eta_\psi:=\sup\left\{\eta\in\mathbb R; \: \xi\mapsto|\xi|^{\eta+\frac{1}{2}}\frac{W_{\phi_+}\left(\frac{1}{2}-\mathrm{i}\xi\right)}{W_{\phi_-}\left(\frac{1}{2}+\mathrm{i}\xi\right)} e^{-\frac{\pi}{2}|\xi|}\in\bmrm{L}(\mathbb R)\right\}\in (0,\infty].
\end{align}
Writing, for $\epsilon>0$, $\mathcal{E}(\epsilon)=\mathrm{Span}\{\mathfrak{h}_{\epsilon,\beta}; \beta>0\}$ where \hptg{C61}{$\mathfrak{h}_{\epsilon,\beta}(x)=e^{-(\frac{1}{2}+\epsilon)x}e^{-\beta e^{-x}}, x \in \mathbb{R}$},  the following holds.
\begin{enumerate}
\item \phantomsection\label{it:2c1} For all $\epsilon>0$, $\mathcal{E}(\epsilon)$ is a dense subset of $\bmrm{L}(\mathbb{R},e)$.
\item \phantomsection\label{it:2c2} For all $0<\epsilon<\eta_\psi$, $\mathcal{E}(\epsilon)\subset\mathbf{D}(H_\psi)$ and $\mathcal{E}_\psi(\epsilon):=H_\psi(\mathcal{E}(\epsilon))$ is a core for $A_\mathtt{2}[\psi]$.
\end{enumerate}
\item\phantomsection\label{it:2d} Let $\psi\in\mathbf{N}_b(\mathbb R)$ be such that, for all $n\in\mathbb N$,
\begin{align}\phantomsection\label{eq:mpsi_bound_2}
	\xi\mapsto |\xi|^n\frac{W_{\phi_+}\left(\frac{1}{2}-\mathrm{i}\xi\right)}{W_{\phi_-}\left(\frac{1}{2}+\mathrm{i}\xi\right)} e^{-\frac{\pi}{2}|\xi|}\in\bmrm[1]{L}(\mathbb R).
\end{align}

Moreover, if $\psi$ satisfies one of the following conditions
\begin{enumerate}[(i)]
	\item\phantomsection\label{conditions_i} $\phi_+(0)>0$

	\item\phantomsection\label{conditions_iii} $\int_{|y|>1} |y|\mu(dy)<\infty$
\end{enumerate}
then $\mathcal{E}_\psi=\!\!\bigcup\limits_{0<\epsilon<\infty}\!\!\!\!\mathcal{E}_\psi(\epsilon)$ is core for  $A_\mathtt{2}[\psi]$. Moreover, on $\mathcal{E}_\psi$,  $A_\mathtt{2}[\psi]$ admits the representation as the following integro-differential operator
\begin{eqnarray}\phantomsection\label{eq:integro_diff}
	A_\mathtt{2}[\psi]f(x)&=&e^{-x}\left(\sigma^2 f''(x)+\mathtt{b}f'(x)-\psi(0)f(x)\right. \nonumber\\
	&+ & \left. \int_\mathbb{R}(f(x+y)-f(x)-y\mathbbm{1}_{\{|y|\leqslant 1\}}f'(x))\mu(dy) \right)
\end{eqnarray}
where $(\psi(0),\mathtt{b},\sigma^2,\mu)$ is the quadruplet  determining $\psi$. 
\end{enumerate}

For any  $f\in\mathbf{D}_\psi \subset \mathbf{S}(\mathbb{R})$, we have
\begin{align} \label{eq:PDO_L}
	A_\mathtt{PDO}[\psi]f(x)=-\frac{e^{-x}}{\sqrt{2\pi}}\int_\mathbb{R} e^{{\rm{i}}\xi  x}\psi(\xi)\mathcal{F}_{f}(\xi)\,d\xi=e^{-x}L[\psi]f(x)
\end{align}
where $L[\psi]$ is the $\bmrm{L}(\mathbb{R})$-generator as well as the Feller-generator  of the L\'evy process with L\'evy-Khintchine exponent $\psi$, see \cite[Section 3.4.1 and Theorem 3.3.3]{Applebaum}. It is known that an operator $(L,\mathbf{D}(L))$ on a Hilbert space $H$ is dissipative if and only if $\textrm{Re}\langle Lf,f\rangle\leqslant 0$ for all $f\in\mathbf{D}(L)$. To check this condition for $A_\mathtt{PDO}[\psi]$ on $\mathbf{D}_\psi\subset\bmrm{L}(\mathbb{R},e)$, we observe that, for all $f\in\mathbf{D}(L)$,
\begin{align}
	&\textrm{Re} \langle A_\mathtt{PDO}[\psi]f, f\rangle_{\bmrm{L}(\mathbb{R},e)}=\textrm{Re}\langle L[\psi]f, f\rangle_{\bmrm{L}(\mathbb{R})}\leqslant 0
\end{align}
as $L[\psi]$ is the $\bmrm{L}(\mathbb{R})$-generator of the L\'evy process, hence dissipative. Thus, $(A_\mathtt{PDO}[\psi],\mathbf{D}_\psi)$ is dissipative.

\phantomsection\label{prop:intertwining_test}
	For any $\psi\in\mathbf{N}_+(\mathbb R)$ we have
	\begin{align}\phantomsection\label{eq:intertwining_pdo_0}
		A_\mathtt{PDO}[\psi]\Lambda_\psi =\Lambda_\psi A_\mathtt{PDO}[\psi_0]\ \mbox{ on } \ \mathbf{C}^\infty_c(\mathbb R).
	\end{align}

 Since the proof is quite technical, we start by outlining the main ideas of its proof. If $m_{\Lambda_\psi}$ extends continuously on $\mathbb{S}_{[0,1]}$ and the conditions of Proposition~\ref{multiplier_result} are met for $f\in\mathbf{C}^\infty_c(\mathbb R)$ with $\gamma=1$, then we get
\begin{align*}
	\mathcal{F}_{\! A_\mathtt{PDO}[\psi]\Lambda_\psi f}(\xi+\mathrm{i})=\mathcal{F}_{L[\psi]\Lambda_\psi f}(\xi)=m_{\Lambda_\psi}(\xi)\psi(\xi)\mathcal{F}_f(\xi)
\end{align*}
where $L[\psi]$ is the generator of the L\'evy process associated to $\psi$. On the other hand, if one takes $\beta=0$ in Proposition~\ref{cor:multiplier}, it is expected that $m_{\Lambda_\psi}$ should satisfy the same functional equation in \eqref{eq:fneq} with $\beta=0$, given that $m_{\Lambda_\psi}(\xi+\mathrm{i})$ is well defined for all $\xi\in\mathbb R$. As a result, a straightforward application of Proposition~\ref{multiplier_result} would imply that
\begin{align*}
	\mathcal{F}_{\Lambda_\psi A_\mathtt{PDO}[\psi_0] f}(\xi+\mathrm{i})=m_{\Lambda_\psi}(\xi+\mathrm{i})\mathcal{F}_{\! A_\mathtt{PDO}[\psi_0] f}(\xi+\mathrm{i})=m_{\Lambda_\psi}(\xi+\mathrm{i})\psi_0(\xi)\mathcal{F}_{f}(\xi)
\end{align*}
which would establish that $\mathcal{F}_{\! A_\mathtt{PDO}[\psi]\Lambda_\psi f}=\mathcal{F}_{\Lambda_\psi A_\mathtt{PDO}[\psi_0]f}$. However, the continuous extension of $m_{\Lambda_\psi}$ on the line $\mathbb R+\mathrm{i}$ is not always guaranteed and this is why we perturb the operator $\Lambda_\psi$ by a parameter $\beta>0$, and resort to Proposition~\ref{cor:multiplier} to prove \eqref{eq:intertwining_pdo_0}. To this end, we recall that $\psi_\beta(\xi)=\xi^2-{\rm{i}}\beta\xi$ for $\beta>0$ and $\xi \in \mathbb{R}$. Also, let us define
\begin{align*}
m_{\Lambda^{\!(\beta)}}(z)=\frac{\Gamma(1+{\rm{i}}z   )}{\Gamma(1+\beta+{\rm{i}}z)}, \ z\in\mathbb{S}_{(-\infty,1)}.
\end{align*}
Clearly, $m_{\Lambda^{\!(\beta)}}$ is analytic and zero-free in $\mathbb{S}_{[0,1)}$. Let  $\Lambda^{\!(\beta)}$ be the shifted Fourier multiplier associated to $m_{\Lambda^{\!(\beta)}}$. Since $m_{\Lambda^{\!(\beta)}}$ is bounded on the line $\mathbb{R}+{\rm{i}}/2$, $\Lambda^{\!(\beta)}\in\mathscr{M}\cap\mathscr{B}(\bmrm{L}(\mathbb{R},e))$.  We note that for any $f\in \mathbf{C}^\infty_c(\mathbb{R})$, $\mathcal{F}_{f}$ is an entire function. Moreover, $m_{\Lambda^{\!(\beta)}}\in\mathbf{A}_{(-\infty,1)}$ and by the Stirling asymptotic formula of Gamma functions, $m_{\Lambda^{\!(\beta)}}$ is uniformly bounded on the \hpt{R24}{strip $\mathbb{S}_{(-\infty, a/2]}$ for any $a<2$}. \hptg{C39}{Also, $\mathcal{F}_f(\cdot+\frac{\mathrm{i} a}{2})\in\bmrm{L}(\mathbb R)$ for all $a<2$, and therefore by Proposition~\ref{multiplier_result}, it follows that $\Lambda^{\!(\beta)}f\in\bmrm{L}(\mathbb{R},e^{ax}dx)$ for any $a<2$.}

\begin{lem}\label{lem:beta}
For any $\beta>0$ we have
\begin{align*}
A_{\mathtt{PDO}}[\psi_\beta]\Lambda^{\!(\beta)} =\Lambda^{\!(\beta)} A_\mathtt{PDO}[\psi_0] \ \mbox{ on } \  \mathbf{C}^\infty_c(\mathbb{R})
\end{align*}
and $\Lambda^{\!(\beta)}(\mathbf{C}^\infty_c(\mathbb{R}))$ is dense in $\bmrm{L}(\mathbb{R},e)$.
\end{lem}
\begin{proof}
By the definition of the  operator $\Lambda^{\!(\beta)}$, the fact that $A_\mathtt{PDO}[\psi_0](\mathbf{C}^\infty_c(\mathbb R))\subset\mathbf{C}^\infty_c(\mathbb R)$ and Proposition~\ref{multiplier_result},
we have, for any $f\in \mathbf{C}^\infty_c(\mathbb{R})$ and writing $d\tilde{\xi}_x=-e^{{\rm{i}}\xi   x}\frac{d\xi}{\sqrt{2\pi}}$,
\begin{eqnarray}
\Lambda^{\!(\beta)} A_\mathtt{PDO}[\psi_0]f(x)&=&-\int_{\mathbb{R}}e^{{\rm{i}}\xi   x}m_{\Lambda^{(\beta)}}(\xi)(\xi-{\rm{i}})   ^2\mathcal{F}_{f}(\xi-{\rm{i}})   \,\frac{d\xi}{\sqrt{2\pi}} \nonumber \\
&=&\int_\mathbb{R} \frac{\Gamma(1+{\rm{i}}\xi  )(\xi-{\rm{i}})^2}{\Gamma(1+\beta+{\rm{i}}\xi  )}\mathcal{F}_{f}(\xi-{\rm{i}})   \,d\tilde{\xi}_x \phantomsection\label{eq:step_2}=\int_\mathbb{R} \frac{\rm{i}\Gamma(2+{\rm{i}}\xi )(\xi-{\rm{i}})}{\Gamma(1+\beta+{\rm{i}}\xi  )}   \mathcal{F}_{f}(\xi-{\rm{i}})   \,d\tilde{\xi}_x \\

&=&e^{-x}\int_\mathbb{R} \frac{{\rm{i}}\Gamma(1+{\rm{i}}\xi  )}{\Gamma(\beta+{\rm{i}}\xi  )}\xi\mathcal{F}_{f}(\xi)\,d\tilde{\xi}_x\phantomsection\label{eq:contour_1}
 =e^{-x}\int_\mathbb{R}\frac{\Gamma(1+{\rm{i}}\xi  )}{\Gamma(1+\beta+{\rm{i}}\xi  )}\psi_\beta(\xi)\mathcal{F}_{f}(\xi)\,d\tilde{\xi}_x  \\ &=&A_\mathtt{PDO}[\psi_\beta]\Lambda^{\!(\beta)}f(x)\phantomsection\label{eq:intertwining_pdo}
\end{eqnarray}
where \eqref{eq:contour_1} follows  by applying Lemma~\ref{prop:contour}. \hptg{C40}{Now, since the adjoint operator $\widehat{\Lambda}^{\!(\beta)}$ is also a shifted Fourier multiplier operator with $m_{\widehat{\Lambda}^{\!(\beta)}}(\xi+{\rm{i}}/2)=m_{\Lambda^{\!(\beta)}}(-\xi+{\rm{i}}/2)\neq 0$ for a.e.~$\xi$, it is bounded and injective, which implies that the image of any dense set under $\Lambda^{(\beta)}$ is dense in $\bmrm{L}(\mathbb{R},e)$. This proves the lemma.}
\end{proof}
\noindent
Now, let $g\in\Lambda^{\!(\beta)}(\mathbf{C}^\infty_c(\mathbb{R}))$, that is  $g=\Lambda^{\!(\beta)}f$, $f\in \mathbf{C}^\infty_c(\mathbb{R})$, and,
\begin{align}\phantomsection\label{eq:W^beta_psi}
m_{\Lambda^{\!(\beta)}_\psi}(z)=W^{(\beta)}_\psi(z)=\frac{W_{\phi_+}(-{\rm{i}}z   )\Gamma(1+{\rm{i}}z+\beta)}{\Gamma(-{\rm{i}}z   )W_{\phi_-}(1+{\rm{i}}z   )} \ \ \mbox{for} \ \  z\in\mathbb{S}_{[0,1)}.
\end{align}
From Proposition~\ref{cor:multiplier}\eqref{it:W_1}, it follows that $m_{\Lambda^{\!(\beta)}_\psi}\in\mathbf{A}_{[0,1]}$. Let $\Lambda^{\!(\beta)}_\psi$ be Fourier operator associated to $m_{\Lambda^{\!(\beta)}_\psi}$. Then, $\Lambda^{\!(\beta)}_\psi\in\mathscr{M}$. Moreover, from our assumption that $\psi\in\mathbf{N}_+(\mathbb{R})$ and the  Stirling asymptotic of the gamma function, it follows that $\left|m_{\Lambda^{\!(\beta)}_\psi}\left(\xi+{\rm{i}}/2\right)\right|={\rm{O}}(|\xi|^\beta)$. From Proposition~\ref{cor:multiplier}\eqref{it:kap}, one gets that
$\xi\mapsto m_{\Lambda^{\!(\beta)}_\psi}(\xi)$ and  $ \xi\mapsto m_{\Lambda^{\!(\beta)}_\psi}(\xi+{\rm{i}})   $ have at most polynomial growth as $|\xi|\to\infty$. On the other hand, from \eqref{eq:step_2} and \eqref{eq:intertwining_pdo}, one can show that
\begin{align*}
A_\mathtt{PDO}[\psi_\beta]g\in\bmrm{L}(\mathbb{R},e)  \mbox{ and }  \mathcal{F}^{e}_{A_\mathtt{PDO}[\psi_\beta]g}(\xi)={\rm{O}}(|\xi|^{-n}) \ \ \mbox{for all $n\in\mathbb{N}$}.
\end{align*}
Hence, the mapping $\xi\mapsto m_{\Lambda^{\!(\beta)}_\psi}\left(\xi+{\rm{i}}/2\right)\mathcal{F}^{e}_{A_\mathtt{PDO}[\psi_\beta]g}(\xi)\in\bmrm{L}(\mathbb{R})\cap\bmrm[1]{L}(\mathbb{R})$,
which ensures that $A_\mathtt{PDO}[\psi_\beta]g\in\mathbf{D}(\Lambda^{\!(\beta)}_\psi)$.
 Therefore, we have,
\begin{align}
\Lambda^{\!(\beta)}_\psi A_{\mathtt{PDO}}[\psi_\beta]g(x)&=\frac{e^{-\frac{x}{2}}}{\sqrt{2\pi}}\int_{\mathbb{R}} e^{{\rm{i}}\xi   x}\mathcal{F}^{e} _{\Lambda^{\!(\beta)}_\psi A_\mathtt{PDO}[\psi_\beta]g}(\xi)\,d\xi \phantomsection\label{line1}\\
&=-\frac{1}{\sqrt{2\pi}}\int_{\mathbb{R}+\frac{{\rm{i}}}{2}} e^{{\rm{i}}z   x}m_{\Lambda^{\!(\beta)}_\psi}(z)\psi_\beta(z-{\rm{i}})   \mathcal{F}_{g}(z-{\rm{i}})   \,dz \phantomsection\label{line1'} \\
&=-\frac{1}{\sqrt{2\pi}}\int_{\mathbb{R}} e^{{\rm{i}}\xi   x}m_{\Lambda^{\!(\beta)}_\psi}(\xi)\psi_\beta(\xi-{\rm{i}})   \mathcal{F}_{g}(\xi-{\rm{i}})   \,d\xi \phantomsection\label{line2}\\
&=-\frac{e^{-x}}{\sqrt{2\pi}}\int_{\mathbb{R}}e^{{\rm{i}}\xi   x}m_{\Lambda^{\!(\beta)}_\psi}(\xi+{\rm{i}})   \psi_\beta(\xi)\mathcal{F}_{g}(\xi)d\xi  \nonumber\\
&=-\frac{e^{-x}}{\sqrt{2\pi}}\int_{\mathbb{R}}e^{{\rm{i}}\xi   x}m_{\Lambda^{\!(\beta)}_\psi}(\xi)\psi(\xi)\mathcal{F}_{g}(\xi)\,d\xi \ \ \nonumber \\
&= A_\mathtt{PDO}[\psi]\Lambda^{\!(\beta)}_\psi g(x). \phantomsection\label{line5}
\end{align}
\hptg{C42}{In the computation above, the second identity follows by a change of variable which is valid since $\psi_\beta$ and $\mathcal{F}_{g}$ are entire functions, and $\mathcal{F}_{A_\mathtt{PDO}[\psi_\beta]g}(\xi)=\psi_\beta(\xi-\mathrm{i})\mathcal{F}_g(\xi-\mathrm{i})$ for all $\xi\in\mathbb R$.} \eqref{line2} follows from \eqref{line1'} and Lemma~\ref{prop:contour}, since $\psi_\beta\mathcal{F}_{g}\in\mathbf{A}_{(-\infty,1)}$ and it decays faster than any polynomial as $|\xi|\to\infty$, and the identity before \eqref{line5} follows from Proposition~\ref{cor:multiplier}\eqref{eq:fneq} and Proposition~\ref{multiplier_result}. Now, recalling the definition of the shifted Fourier multiplier operator $\Lambda_\psi$, we note that $m_{\Lambda^{\!(\beta)}_\psi} m_{\Lambda^{\!(\beta)}}=m_{\Lambda_\psi}$ on $\mathbb{S}_{(0,1)}$, which implies that $\Lambda_\psi=\Lambda^{\!(\beta)}_\psi\Lambda^{\!(\beta)}$. Then, plugging in $g=\Lambda^{\!(\beta)}f$ in the above computation along with Lemma~\ref{lem:beta}, \eqref{eq:intertwining_pdo_0} follows.

\label{lem:beta}
For any $\beta>0$ we have
\begin{align*}
A_{\mathtt{PDO}}[\psi_\beta]\Lambda^{\!(\beta)} =\Lambda^{\!(\beta)} A_\mathtt{PDO}[\psi_0] \ \mbox{ on } \  \mathbf{C}^\infty_c(\mathbb{R})
