&=&\int_\mathbb{R} \frac{\Gamma(1+{\rm{i}}\xi  )(\xi-{\rm{i}})^2}{\Gamma(1+\beta+{\rm{i}}\xi  )}\mathcal{F}_{f}(\xi-{\rm{i}})   \,d\tilde{\xi}_x \phantomsection\label{eq:step_2}=\int_\mathbb{R} \frac{\rm{i}\Gamma(2+{\rm{i}}\xi )(\xi-{\rm{i}})}{\Gamma(1+\beta+{\rm{i}}\xi  )}   \mathcal{F}_{f}(\xi-{\rm{i}})   \,d\tilde{\xi}_x \\

&=&e^{-x}\int_\mathbb{R} \frac{{\rm{i}}\Gamma(1+{\rm{i}}\xi  )}{\Gamma(\beta+{\rm{i}}\xi  )}\xi\mathcal{F}_{f}(\xi)\,d\tilde{\xi}_x\phantomsection\label{eq:contour_1}
