	We recall, from the proof of Proposition~\ref{dense_range_intertwining}, that $\mathcal{D}_k$ is a core for $\Lambda_k$ if and only if $\mathcal{F}^{e}_{\mathcal{D}_k}$ is dense in $\bmrm{L}(\mathbb R,1+|m^e_{\Lambda_k}|^2)$. Let us write $\mathbf{m}=\prod_{k=1}^d (1+|m^e_{\Lambda_k}|^2)$. Then, it follows that
\begin{align*}
	\bigotimes_{k=1}^d \bmrm{L}(\mathbb R,1+|m^e_{\Lambda_k}|^2)=\bmrm{L}(\mathbb R^d,\mathbf{m})
\end{align*}
and therefore, $\bm{\mathcal D}$ is dense in $\bmrm{L}(\mathbb R^d,{\bf m})$. Since $\mathbf{m}\geqslant 1+\prod_{k=1}^d |m^e_{\Lambda_k}|^2=1+|\mathbf{m}^{\bf e}_{\bm{\Lambda}}|^2$, this implies that $\bm{\mathcal D}$ is also dense in $\bmrm{L}(\mathbb R^d, 1+|\mathbf{m}^{\bf e}_{\bm{\Lambda}}|^2)$. Therefore, $\bm{\mathcal{D}}$ is a core for $\bm{\Lambda}$.

\phantomsection\label{prop:tensor_intertwining}
Let, for each $k=1, \ldots,d$, $A_k, B_k \in \mathscr{D}(\bmrm{L}(\mathbb{R},e))$ and $(\Lambda_k,\mathbf{D}(\Lambda_k)) \in \mathscr{M}$, and, assume that there exists a dense subset $\mathcal{D}_k$ of $\bmrm{L}(\mathbb{R},e)$ such that
$ A_k\Lambda_k=\Lambda_k B_k  \mbox{ on } \mathcal{D}_k$. Then,
\begin{align}\phantomsection\label{eq:tensor_intertwining_id}
\bm{A}\bm{\Lambda}=\bm{\Lambda}\bm{B} \ \ \ \mbox{on \ $\bm{\mathcal D}$}
\end{align}
where $\bm{\mathcal D}=\otimes_{k=1}^d \mathcal{D}_k$, $\bm{A}=\otimes_{k=1}^d A_k, \ \bm{B}=\otimes_{k=1}^d B_k$, and $\bm{\Lambda}=\otimes_{k=1}^d \Lambda_k$. In particular, when the $A_k,B_k$'s are bounded operators and $\mathcal{D}_k$ is a core for $\Lambda_k$ for each $k$, the above identity extends to $\mathbf{D}(\bm{\Lambda})$.

 Since any $\mathbf{f}\in\bm{\mathcal D}=\otimes_{k=1}^d\mathcal{D}_k$ \hptg{C78}{is a linear combination of functions of the form} $\mathbf{f}(\bm{x})=\prod_{k=1}^d f_k(x_k)$,
	where $\bm{x}=(x_1,\ldots, x_d)$ and $f_k\in\mathcal{D}_k$, by the definition of the tensor product of operators, we have
	\begin{equation}\phantomsection\label{eq:tens_int_pf}
		\begin{aligned}
			\bm{A}\bm{\Lambda}\mathbf{f}&=\bm{A}(\otimes_{k=1}^d\Lambda_k f_k)
			=\otimes_{k=1}^d A_k\Lambda_k f_k=\otimes_{k=1}^d \Lambda_k B_k f_k =\bm{\Lambda}\bm{B}\mathbf{f},
		\end{aligned}
	\end{equation}
which proves \eqref{eq:tensor_intertwining_id}. When $A_k,B_k$ are bounded operators, so are $\bm{A}$ and $\bm{B}$. Moreover, if $\mathcal{D}_k$ is a core for $\Lambda_k$ for $k=1,\ldots ,d$, then by Lemma~\ref{lem:core_tensor}, $\bm{\mathcal D}=\otimes_{k=1}^d\mathcal{D}_k$ is a core for $\bm{\Lambda}$. Therefore, boundedness of $\bm{A}, \bm{B}$ and {closedness} of $\bm{\Lambda}$ ensure that \eqref{eq:tens_int_pf} extends for all $\mathbf{f}\in\mathbf{D}(\bm{\Lambda})$.

