Then, $J_{\psi}$  is an entire function and $J_{\psi}\in \mathbf{C}_0([-\infty,\infty))$. Moreover, if\[\xi\mapsto m_{H_\psi}\left(\xi+\frac{{\rm{i}}}{2}   \right)=\frac{\Gamma(\frac{1}{2}-{\rm{i}}\xi   )}{W_{\phi}(\frac{1}{2}+\mathrm{i}\xi)}\in\bmrm{L}(\mathbb{R}) \] then $J_{\psi}\in\bmrm{L}(\mathbb{R},e)$ and $\uptau_{-y}J_{\psi}$ is an eigenfunction of $P_t[\psi]$ corresponding to the eigenvalue $e^{-te^{-y}}.$

 Since $\phi$ is increasing, we have  $W_{\phi}(n+1)\geqslant\phi(1)^n$ for all $n$ and therefore, the series defining $J_{\psi}$ converges absolutely for all $z\in\mathbb{C}$. Now, consider the function
\begin{align*}
J(x)=\sum_{n=0}^\infty(-1)^n\frac{e^{nx}}{(n!)^2}=J_0\left(2e^{\frac{x}{2}}\right)
\end{align*}
where $J_0$ is the Bessel function of index $0$. It is well-known that $J_0\in \mathbf{C}_0([0,\infty))$ which implies that $J\in \mathbf{C}_0([-\infty,\infty))$. Also,
\begin{align*}
\Lambda^b_\psi J(x)&=\mathbb{E}[J(x-{I}_\psi)]
=\mathbb{E}\left[\sum_{n=0}^\infty(-1)^n\frac{1}{(n!)^2}e^{n(x-{I}_\psi)}\right]
=\sum_{n=0}^\infty (-1)^n\frac{1}{(n!)^2}e^{nx}\mathbb{E}[e^{-n{I}_\psi}],
\end{align*}
where the interchange of the sum and expectation is justified as the series in the right-hand side is absolutely convergent. Recalling that $\mathbb{E}[e^{-n{I}_\psi}]=\frac{n!}{W_{\phi}(n+1)}$, we obtain $J_{\psi}=\Lambda^b_\psi J$. From Proposition~\ref{C0_intertwining}, we get that $J_{\psi}\in \mathbf{C}_0([-\infty,\infty))$. Now, from Theorem~\ref{thm:spectrum}, we know that $P_t[\psi]$ has point spectrum when $m_{H_\psi}(\cdot+\frac{{\rm{i}}}{2}   )\in\bmrm{L}(\mathbb{R})$ and the eigenfunction corresponding to the eigenvalue $e^{-te^{-y}}$ is given by $\uptau_{-y}K_\psi$, where $K_\psi=\widehat{\mathcal{F}^{e}}(m_{H_\psi}(\cdot+\frac{{\rm{i}}}{2}))$. The rest of the proof is devoted to show that $K_\psi=J_{\psi}$. For each $\kappa>1$, let $\mathfrak{f}_\kappa(x)=\kappa e^{-\kappa x}e^{-e^{-\kappa x}}$. Then, $\int_\mathbb{R}\mathfrak{f}_\kappa(x)\,dx=1$. From the proof of Theorem~\ref{thm:spectrum}, we know that $H_\psi\mathfrak{f}_\kappa=K_\psi\ast\mathfrak{f}_\kappa$. On the other hand,
\begin{align*}
H_\psi\mathfrak{f}_\kappa(x)&=e^{-\frac{x}{2}}\frac{1}{\sqrt{2\pi}}\int_{\mathbb{R}}\mathcal{F}^{e}_ {H_\psi\mathfrak{f}_\kappa}(\xi)e^{{\rm{i}}\xi x}\,d\xi
=\frac{1}{\sqrt{2\pi}}\int_{\mathbb{R}}e^{{\rm{i}}\xi x}m_{H_\psi}\left(\xi+\frac{{\rm{i}}}{2}   \right)\mathcal{F}_{\mathfrak{f}_\kappa}\left(\xi+\frac{{\rm{i}}}{2}   \right)\,d\xi \\
&=\frac{1}{\sqrt{2\pi}}e^{-\frac{x}{2}}\int_{\mathbb{R}}e^{{\rm{i}}\xi x}\frac{\Gamma(\frac{1}{2}-{\rm{i}}\xi   )}{W_{\phi}(\frac{1}{2}+\mathrm{i}\xi)}\mathcal{F}_{\mathfrak{f}_\kappa}\left(\xi+\frac{{\rm{i}}}{2}   \right)\,d\xi\\
&=\frac{1}{\sqrt{2\pi}}\int_{-\infty+\frac{{\rm{i}}}{2}   }^{\infty+\frac{{\rm{i}}}{2}   } e^{{\rm{i}}zx}\frac{\Gamma(-{\rm{i}}z   )}{W_{\phi}(1+{\rm{i}}z)   }\Gamma\left(1+\frac{{\rm{i}}z}{\kappa}\right)\,dz \\
&=\frac{1}{\sqrt{2\pi}}\int_{-\infty+\frac{{\rm{i}}}{2}   }^{\infty+\frac{{\rm{i}}}{2}   }e^{{\rm{i}}zx}\frac{\pi\Gamma(1+\frac{{\rm{i}}z}{\kappa})}{W_{\phi}(1+{\rm{i}}z)   \sin(-i\pi z)\Gamma(1+{\rm{i}}z)   }\,dz \\
&=:\frac{1}{\sqrt{2\pi}}\int_{-\infty+\frac{{\rm{i}}}{2}   }^{\infty+\frac{{\rm{i}}}{2}   }e^{{\rm{i}}zx}G_\kappa(z)\,dz.
\end{align*}
To compute the above integral, we fix $B>0$, a positive odd integer $N$ and consider the rectangular contour formed by the points $-B+\frac{{\rm{i}}}{2}   , B+\frac{{\rm{i}}}{2}   , B-{\rm{i}}{N\over 2}, -B-{\rm{i}}\frac{N}{2}$ with clockwise orientation. The poles of $G_\kappa$ in this rectangle are $\{0,-\mathrm{i},-2\mathrm{i},\ldots, -\lfloor\frac{N}{2}\rfloor \mathrm{i}\}$ with residues $(-1)^n\frac{\Gamma(1+\frac{n}{\kappa})}{n!W_{\phi}(n+1)}$, $n=0,1,2,\ldots, \lfloor\frac{N}{2}\rfloor$. We split the contour integral into the following four parts
\begin{align}
&I^{(1)}_B=\int_{-B+\frac{{\rm{i}}}{2}   }^{B+\frac{{\rm{i}}}{2}   }e^{{\rm{i}}zx}G_\kappa(z)\,dz, \  I^{(2)}_{B,N}=\int_{B-{\rm{i}}\frac{N}{2}}^{B+\frac{{\rm{i}}}{2}   }e^{{\rm{i}}zx}G_\kappa(z)\,dz\nonumber \\
&I^{(3)}_{B,N}=\int_{-B-{\rm{i}}\frac{N}{2}}^{-B+\frac{{\rm{i}}}{2}   }e^{{\rm{i}}zx}G_\kappa(z)\,dz , \ I^{(4)}_{B,N}=\int_{-B-{\rm{i}}\frac{N}{2}}^{B-{\rm{i}}\frac{N}{2}}e^{{\rm{i}}zx}G_\kappa(z)\,dz .\nonumber
\end{align}
Since the integrals $I^{(2)}_{B,N}$ and $I^{(3)}_{B,N}$ are similar, we deal with only one of them, say $I^{(2)}_{B,N}$. For any fixed $N$, we observe that, for large values of $B$,
\begin{align*}
 \sup_{t\in [-\frac{N}{2},\frac{1}{2}]}\left|\frac{\Gamma(1-\frac{t}{\kappa}+{\rm{i}}\frac{B}{\kappa})}{W_{\phi}(1-t+\mathrm{i} B)\sin(\pi(t-\mathrm{i} B))\Gamma(1-t+{\rm{i}}\xi   )}\right|\leqslant C_Ne^{-\frac{\pi}{2\kappa}|B|}.
\end{align*}
Therefore, for fixed $N$, $I^{(2)}_{B,N}\to 0, I^{(3)}_{B,N}\to 0$ as $B\to\infty$. For $I^{(4)}_{B,N}$ we proceed as follows. First, we observe that
$$\left|W_{\phi}\left(1+\frac{N}{2}+\mathrm{i}\xi\right)\right|\geqslant\left|W_{\phi}\left(\frac{1}{2}+\mathrm{i}\xi\right)\right|\phi(1)^{\frac{N}{2}}.$$
Then, for any odd natural number $N$,
\begin{align}
|I^{(4)}_{B,N}|&\leqslant\int_{-B}^B\frac{e^{\frac{Nx}{2}}\left|\Gamma(1+\frac{N}{2\kappa}+\frac{{\rm{i}}\xi }{\kappa})\right|}{|W_{\phi}(\frac{N}{2}+1+\mathrm{i}\xi)||\sin(-\frac{N\pi}{2}-\mathrm{i}\pi\xi)||\Gamma(1+\frac{N}{2}+\mathrm{i}\xi)|}\,d\xi \nonumber \\
&\leqslant e^{\frac{Nx}{2}}\phi(1)^{-\frac{N}{2}}\int_{-\infty}^\infty\left|\frac{\Gamma(1+\frac{N}{2\kappa}+\frac{{\rm{i}}\xi }{\kappa})}{W_{\phi}(\frac{1}{2}+\mathrm{i}\xi)\cosh(\pi\xi)\Gamma(1+\frac{N}{2}+\mathrm{i}\xi)}\right|\,d\xi \phantomsection\label{eq:stirling_1} \\
&\leqslant Ce^{\frac{Nx}{2}}\phi(1)^{-\frac{N}{2}}\left(\frac{N}{2}\right)^{\frac{N}{2}(\frac{1}{\kappa}-1)}\int_{-\infty}^\infty\left|\frac{1}{W_{\phi}(\frac{1}{2}+\mathrm{i}\xi)\cosh(\pi\xi)}\right|\,d\xi\to 0 \phantomsection\label{eq:stirling_2}
\end{align}
as $N\to\infty$ since $\kappa>1$ and \eqref{eq:stirling_2} follows from \eqref{eq:stirling_1} by Stirling approximation. Therefore, $I^{(4)}_{B,N}\to 0$ uniformly in $B$ as $N\to\infty$. Finally, using the residue theorem for meromorphic functions, we conclude that, for all $x\in\mathbb{R}$,
\begin{align*}
H_\psi\mathfrak{f}_\kappa(x)=\sum_{n=0}^\infty (-1)^n\frac{\Gamma(1+\frac{n}{\kappa})}{n! W_{\phi}(n+1)}e^{nx} .
\end{align*}
On the other hand, it is easy to see that, for all $x\in\mathbb{R}$ and $\kappa>1$,
\begin{align*}
J_{\psi}\ast\mathfrak{f}_\kappa (x)=\sum_{n=0}^\infty (-1)^n\frac{\Gamma(1+\frac{n}{\kappa})}{W_{\phi}(n+1)n!}e^{nx} .
\end{align*}
 Therefore, $K_\psi\ast\mathfrak{f}_\kappa(x)=J_{\psi}\ast\mathfrak{f}_\kappa(x)$ for all $x\in\mathbb{R}$ and $\kappa>1$. Finally, the proof of the proposition will be completed by means of the following lemma.

We first recall the fact that, for any $g\in\bmrm{L}(\mathbb{R},e)$, $\lim_{t\to 0}\|\uptau_tg-g\|_{\bmrm{L}(\mathbb R,e)}=0$ and $\hpt{R38}{\|\uptau_t g\|_{\bmrm{L}(\mathbb{R},e)}=e^{-\frac{t}{2}}\|g\|_{\bmrm{L}(\mathbb{R},e)}}$ for all $t\in\mathbb{R}$. Now, for any $\kappa>1$, $g\ast\mathfrak{f}_\kappa\in\bmrm{L}(\mathbb{R},e)$ and
\begin{align}
\|g\ast\mathfrak{f}_\kappa-g\|^2_{\bmrm{L}(\mathbb{R},e)}&=\int_\mathbb{R} e^x\left(\int_\mathbb{R}(\uptau_{-y}g(x)-g(x))\mathfrak{f}_\kappa(y)\,dy\right)^2\,dx \nonumber \\
&\leqslant\int_\mathbb{R} e^x\left(\int_\mathbb{R}(\uptau_{-y}g(x)-g(x))^2\mathfrak{f}_\kappa(y)\,dy\right)\,dx \nonumber \\
&=\int_{\mathbb{R}}\|\uptau_{-y}g-g\|^2_{\bmrm{L}(\mathbb{R},e)}\mathfrak{f}_\kappa(y)\,dy=\int_{\mathbb{R}}\|\uptau_{-\frac{y}{\kappa}}g-g\|^2_{\bmrm{L}(\mathbb{R},e)}\mathfrak{f}_1(y)\,dy. \phantomsection\label{dct}
\end{align}
Next,
$$\int_\mathbb{R}\|\uptau_{-\frac{y}{\kappa}}g-g\|^2_{\bmrm{L}(\mathbb{R},e)}\ \mathfrak{f}_1(y)\,dy\leqslant\int_\mathbb{R}(1+e^{\frac{y}{\kappa}})\|g\|^2_{\bmrm{L}(\mathbb{R},e)}\ \mathfrak{f}_1(y)\,dy=\|g\|^2_{\bmrm{L}(\mathbb{R},e)}\left(1+\Gamma\left(1-\frac{1}{\kappa}\right)\right)$$
and the right-hand side is bounded with respect to $\kappa$. Hence, by applying the dominated convergence theorem, one gets,  as $\kappa\to\infty$,
\begin{align*}
\int_\mathbb{R} \|\uptau_{-\frac{y}{\kappa}} g-g\|^2_{\bmrm{L}(\mathbb{R},e)}\mathfrak{f}_1(y)dy\to 0.
\end{align*}
From \eqref{dct}, it follows that $\|g\ast\mathfrak{f}_\kappa-g\|_{\bmrm{L}(\mathbb{R},e)}\to 0$ as $\kappa\to\infty$. Hence, there exists a sequence $(\kappa_n)$ of positive real numbers such that as $n \to \infty$, $\kappa_n\to\infty$ such that $g\ast\mathfrak{f}_{\kappa_n}\to g$ a.e. On the other hand, for $h\in \mathbf{C}_b(\mathbb{R})$, $h\ast\mathfrak{f}_\kappa(x)=\int_{\mathbb{R}}h(x-\frac{y}{\kappa})\mathfrak{f}_1(y)\,dy\to h(x)$ as $\kappa\to\infty$ by continuity of $h$ and the bounded convergence theorem. Therefore, letting $n\to\infty$ on the identity $g\ast\mathfrak{f}_{\kappa_n}=h\ast\mathfrak{f}_{\kappa_n}$, the proof of the lemma follows.

Let $\phi\in\mathbf{B}$ be such that $\mathfrak{m}=m+\overline{\mu}(0+)<\infty$, then
\begin{align}\phantomsection\label{eq:w_phi_est}
|W_\phi(a+{\rm{i}}\xi)|\asymp\sqrt{\phi(a)} W_\phi(a)e^{-\frac{\pi}{2}|\xi|} |\xi|^{a+\frac{\mathfrak{m}}{\mathtt{d}}-\frac{1}{2}}, \ \ \forall a>0,
\end{align}
if and only if $w\mapsto\int_0^\infty\cos(wy)\overline{\nu}(y)\,dy \in \bmrm[1]{L}(\mathbb{R})$, where $\overline{\nu}$ is the tail of the measure $e^{-ay}\mu(dy)$.

First note that, from  \cite[Theorem 6.2(1)]{patiesavov}, we have, for all $a>0$,
\begin{align*}
|W_{\phi}(a+{\rm{i}}\xi)   |\asymp\frac{\sqrt{\phi(a)}W_\phi(a)}{\sqrt{\phi(a+{\rm{i}}\xi)   }}e^{-|\xi|\Theta_\phi(a,|\xi|)} \ \ \ \mbox{as $|\xi|\to\infty$}
\end{align*}
where
\begin{align*}
|\xi|\Theta_\phi(a,|\xi|)=\int_a^\infty\ln\left(\frac{|\phi(y+\mathrm{i}|\xi|)|}{\phi(y)}\right)\,dy
\end{align*}
which, from the proof of  \cite[Theorem 3.2]{patie2018}, turns out to be
\begin{align}\phantomsection\label{eq:arg}
\Theta_\phi(a,|\xi|)=\int_0^{|\xi|}\arg(\phi(a+\mathrm{i}w))\,dw.
\end{align}
As $\mathtt{d}>0$, $|\phi(a+{\rm{i}}\xi)   |\sim \mathtt{d}|\xi|$ as $|\xi|\to\infty$. Thus, it is enough to show that $e^{-|\xi|\Theta_\phi(a,|\xi|)}\asymp |\xi|^{\frac{\mathfrak{m}}{\mathtt{d}}+a}e^{-\frac{\pi}{2}|\xi|}$. If $z=a+\mathrm{i}w$, then
\begin{align*}
\phi(z)=z\left(\frac{\mathfrak{m}}{z}+\mathtt{d}-\frac{1}{z}\int_0^\infty e^{-zy}\mu(dy)\right)=zg(z).
\end{align*}
Now, $\arg(g(z))=\arctan\left(\frac{\textrm{Im}(g(z))}{\textrm{Re}(g(z))}\right)$. We observe that
\begin{align}
\textrm{Re}(g(a+\mathrm{i}w))&=\mathtt{d}+{\rm{O}}\left(\frac{1}{w}\right) \phantomsection\label{eq:real_part}\\
\textrm{Im}(g(a+\mathrm{i}w))&=-\frac{\mathfrak{m}}{w^2+a^2}+\frac{w}{w^2+a^2}\int_0^\infty\sin(wy)e^{-ay}\mu(dy)+{\rm{O}}\left(\frac{1}{w^2}\right). \phantomsection\label{eq:im_part}
\end{align}
From \eqref{eq:real_part} and \eqref{eq:im_part}, we get
\begin{align}
\frac{\textrm{Im}(g(a+\mathrm{i}w))}{\textrm{Re}(g(a+\mathrm{i}w))}=-\frac{\mathfrak{m}}{\mathtt{d}w}+\frac{\frac{w}{w^2+a^2}\int_0^\infty\sin(wy)e^{-ay}\mu(dy)}{\textrm{Re}(g(a+\mathrm{i}w))}+{\rm{O}}\left(\frac{1}{w^2}\right). \phantomsection\label{eq:ratio_real_im}
\end{align}
Now, let us analyze the second term in the above expression. Using integration by parts (or, equivalently, Fubini's theorem), we have
\begin{align}
\frac{\frac{w}{w^2+a^2}\int_0^\infty\sin(wy)e^{-ay}\mu(dy)}{\textrm{Re}(g(a+\mathrm{i}w))}=\frac{\frac{w^2}{w^2+a^2}\int_0^\infty\cos(wy)\overline{\nu}(y)\,dy}{\textrm{Re}(g(a+\mathrm{i}w))}. \phantomsection\label{eq:im_part2}
\end{align}
As $\textrm{Re}(g(a+\mathrm{i}w))=\mathtt{d}+{\rm{O}}\left(\frac{1}{w}\right)$, the right-hand side of \eqref{eq:im_part2} is integrable with respect to $w$ if and only if the function $w\mapsto\int_0^\infty\cos(wy)\overline{\nu}(y)\,dy$ is integrable with respect to $w$. Also, we observe that $\frac{\textrm{Im}(g(a+\mathrm{i}w))}{\textrm{Re}(g(a+\mathrm{i}w))}\to 0 \ \ \mbox{as $w\to\infty$}$ implies that
\begin{align}
&\arctan\left(\frac{\textrm{Im}(g(a+\mathrm{i}w))}{\textrm{Re}(g(a+\mathrm{i}w))}\right)-\frac{\textrm{Im}(g(a+\mathrm{i}w))}{\textrm{Re}(g(a+\mathrm{i}w))}={\rm{O}}\left(\left|\frac{\textrm{Im}(g(a+\mathrm{i}w))}{\textrm{Re}(g(a+\mathrm{i}w))}\right|^2\right).\phantomsection\label{eq:arctan_g}
\end{align}
From \eqref{eq:ratio_real_im}, it is not hard to see that $\int_0^\infty\left|\frac{\textrm{Im}(g(a+\mathrm{i}w))}{\textrm{Re}(g(a+\mathrm{i}w))}\right|^2\,dw<\infty$. Thus, \eqref{eq:im_part2} and \eqref{eq:arctan_g} yield that
\begin{align*}
\int_0^{|\xi|}\arctan(g(a+\mathrm{i}w))\,dw=-\frac{\mathfrak{m}}{\mathtt{d}}\ln |\xi|+{\rm{O}}(1).
\end{align*}
Finally, $\lim_{w\to\infty}\textrm{Re}(g(a+\mathrm{i}w))=\mathtt{d}=\lim_{w\to\infty} g(a+\mathrm{i}w)>0$ implies that for large values of $w$, $\arg(\phi(a+\mathrm{i}w))=\arg(a+\mathrm{i}w)+\arg(g(a+\mathrm{i}w))$. Therefore,
\begin{align*}
|\xi|\Theta_\phi(a,|\xi|)&=\int_0^{|\xi|}\arg(\phi(a+\mathrm{i}w))\,dw \\
&=\int_0^{|\xi|}\arg(a+\mathrm{i}w)\,dw+\int_0^{|\xi|}\arg(g(a+\mathrm{i}w))\,dw+{\rm{O}}(1) \\
&=|\xi|\arctan\left(\frac{|\xi|}{a}\right)-\frac{a}{2}\ln\left(1+\frac{\xi^2}{a^2}\right)-\frac{\mathfrak{m}}{\mathtt{d}}\ln |\xi|+{\rm{O}}(1) \\
&=\frac{\pi}{2}|\xi|-a\ln |\xi|-\frac{\mathfrak{m}}{\mathtt{d}}\ln |\xi| +{\rm{O}}(1).
\end{align*}
Then, we conclude that
\begin{align*}
e^{-|\xi|\Theta_\phi(a,|\xi|)}\asymp |\xi|^{a+\frac{\mathfrak{m}}{\mathtt{d}}} e^{-\frac{\pi}{2}|\xi|}
\end{align*}
if and only if $w\mapsto\int_0^\infty\cos(wy)\overline{\nu}(y)\,dy$ is in $\bmrm[1]{L}(\mathbb{R})$.
This concludes the proof of the lemma.

It is immediate that the Bernstein-gamma functions corresponding to $\phi_-$ and $\phi_+$ are  given by
\begin{equation*}
\begin{aligned}
&W_{\phi_+}(z)=\frac{\Gamma(\tilde{\alpha} z)}{\Gamma(\tilde{\alpha})}\textrm{ and }
 W_{\phi_-}(z)=\frac{\Gamma(\rho+\alpha z)}{\Gamma(\alpha+\rho)} \ \  z\in\mathbb{C}_{(0,\infty)}.
\end{aligned}
\end{equation*}

\begin{enumerate}[(i)]
\item If $\tilde{\alpha}>\alpha$, or, $\alpha=\tilde{\alpha}$ and  $\rho>\frac{1}{2}$, then $e^{t\mathbb{R}_-}\subseteq\sigma_p(P_t[\psi])$ and the eigenfunction corresponding to the eigenvalue $e^{-te^{-y}}$ is given by $\uptau_{-y}J_{\psi}$ where
\begin{align*}
J_{\psi}(x)=\mathtt{W}\left(\frac{\alpha}{\tilde{\alpha}},\alpha+\rho; -e^{\frac{x}{\tilde{\alpha}}}\right)
\end{align*}
and $\mathtt{W}(\gamma,\beta;z)=\sum_{n=0}^\infty\frac{1}{\Gamma(\gamma n+\beta)}\frac{z^n}{n!}$ is the Wright hypergeometric function, which defines an entire function if $\gamma>-1$.
\item If  $\tilde{\alpha}<\alpha$, then $e^{t\mathbb{R}_-}\subseteq\sigma_r(P_t[\psi])$ and the co-eigenfunction corresponding to $e^{-te^{-y}}$ is given by $\uptau_{-y}J_{\overline{\psi}}$ where
\begin{align}\phantomsection\label{eq:co-eigenfunction_1}
J_{\overline{\psi}}(x)=e^{\frac{\rho x}{\alpha}}\mathtt{W}\left(\frac{\tilde{\alpha}}{\alpha},\tilde{\alpha}+\frac{\tilde{\alpha}}{\alpha}\rho; -e^{\frac{x}{\alpha}}\right).
\end{align}
\end{enumerate}

The proof will be again based on the integration of the multiplier function on a suitable contour. Assuming the condition (i) or (ii), from the proof of Theorem~\ref{thm:spectrum}, we know that
\begin{align*}
J_{\psi}(x)=e^{-\frac{x}{2}}\widehat{\mathcal{F}}\left(m_{H_\psi}\left(\cdot+\frac{{\rm{i}}}{2}   \right)\right)(x). \nonumber
\end{align*}
Let us assume that $\tilde{\alpha}>\alpha$. Then, $m_{H_\psi}\left(\cdot+\frac{{\rm{i}}}{2}   \right)\in\bmrm[1]{L}(\mathbb{R})$. Therefore, by Fourier inversion we get
\begin{align*}
J_{\psi}(x)&=\frac{1}{\sqrt{2\pi}}\int_{-\infty+\frac{{\rm{i}}}{2}   }^{\infty+\frac{{\rm{i}}}{2}   }\frac{\Gamma(-\mathrm{i}\tilde{\alpha} z)}{\Gamma(\rho+\alpha(1+{\rm{i}}z)   )}e^{{\rm{i}}zx}\,dz \nonumber

:=\frac{1}{\sqrt{2\pi}}\int_{-\infty+\frac{{\rm{i}}}{2}   }^{\infty+\frac{{\rm{i}}}{2}   } G(z)e^{{\rm{i}}zx}\,dz. \nonumber
\end{align*}
Choosing the rectangular contour with vertices $-R, R, R-{\rm{i}}\frac{N}{2\tilde{\alpha}}, -R-{\rm{i}}\frac{N}{2\tilde{\alpha}}$, where $N$ is an odd natural number, we define the integrals on the four segments as
\begin{equation} \nonumber
\begin{aligned}
&I^{(1)}_R=\frac{1}{\sqrt{2\pi}}\int_{-R}^R G(z)e^{{\rm{i}}zx}\,dz , \ \ \ I^{(2)}_{R,N}=\frac{1}{\sqrt{2\pi}}\int_{-R}^{-R-{\rm{i}}\frac{N}{2\tilde{\alpha}}} G(z)e^{{\rm{i}}zx}\,dz \\
&I^{(3)}_{R,N}=\frac{1}{\sqrt{2\pi}}\int_{R}^{R-{\rm{i}}\frac{N}{2\tilde{\alpha}}} G(z)e^{{\rm{i}}zx}\,dz, \ \ \ I^{(4)}_{R,N}=\frac{1}{\sqrt{2\pi}}\int_{-R-{\rm{i}}\frac{N}{2\tilde{\alpha}}}^{R-{\rm{i}}\frac{N}{2\tilde{\alpha}}} G(z)e^{{\rm{i}}zx}\,dz.
\end{aligned}
\end{equation}
We note that the poles of the function $G$ in the rectangle are $\left\{0,-\frac{\rm{i}}{\tilde{\alpha}},\ldots, -{\rm{i}}\frac{\lfloor\frac{N}{2}\rfloor}{\tilde{\alpha}}\right\}$ with residues $\frac{1}{\tilde{\alpha} n!\Gamma(\frac{n\alpha}{\tilde{\alpha}}+\alpha+\rho)}$.
Arguing as in the proof of Proposition~\ref{prop:one_sided_jump}, for any fixed $N$, one can show $I^{(2)}_{R,N}, I^{(3)}_{R,N}\to 0$ as $R\to\infty$. On the other hand, after a change of variable,
\begin{align}
I^{(4)}_{R,N}&=\frac{1}{\sqrt{2\pi}}e^{\frac{Nx}{2\alpha}}\int_{-R}^R \frac{\Gamma(-\frac{N}{2}-{\rm{i}}\tilde{\alpha}\xi)}{\Gamma(\rho+\alpha+\frac{N}{2}+{\rm{i}}\alpha\xi)}e^{{\rm{i}}\xi x}\,d\xi \nonumber \\
&=\frac{e^{\frac{Nx}{2\alpha}}}{\sqrt{2\pi}}\int_{-R}^R\frac{\pi e^{{\rm{i}}\xi x}}{\cosh(\pi\tilde{\alpha}\xi)\Gamma(1+\frac{N}{2}+\mathrm{i}\tilde{\alpha}\xi)\Gamma(\rho+\alpha+\frac{N\alpha}{2\tilde{\alpha}}+{\rm{i}}\alpha\xi)}\,d\xi. \nonumber
\end{align}
Using Stirling formula, we have for all $\xi\in\mathbb{R}$,
\begin{equation}
\begin{aligned}
&\left|\Gamma\left(1+\frac{N}{2}+\mathrm{i}\tilde{\alpha}\xi\right)\right|\geqslant\frac{\Gamma(1+\frac{N}{2})}{\cosh^{\frac{1}{2}}(\tilde{\alpha}\pi\xi)} \nonumber \\
&\left|\Gamma\left(\rho+\alpha+\frac{N\alpha}{2\tilde{\alpha}}+\mathrm{i}\alpha\xi\right)\right|\geqslant\frac{\Gamma(1+\frac{N\alpha}{2\tilde{\alpha}}+\alpha+\rho)}{\cosh^{\frac{1}{2}}(\alpha\pi\xi)} \nonumber
\end{aligned}
\end{equation}
and, then
\begin{align*}
|I^{(4)}_{R,N}|\leqslant \frac{e^{\frac{Nx}{2\alpha}}}{\sqrt{2\pi}\Gamma(1+\frac{N}{2})\Gamma(\rho+\alpha+\frac{N\alpha}{2\tilde{\alpha}})}\int_{-\infty}^\infty \frac{\cosh^{\frac{1}{2}}(\tilde{\alpha}\pi\xi)\cosh^{\frac{1}{2}}(\alpha\pi\xi)}{\cosh(\tilde{\alpha}\pi\xi)}\,d\xi.
\end{align*}
As $\tilde{\alpha}>\alpha$, the integral on the right-hand side is finite and hence, $I^{(4)}_{R,N}\to 0$ as $N\to\infty$, uniformly in $R$. Thus, invoking Cauchy integral formula, we have
\begin{align*}
J_{\psi}(x)=\sum_{n=0}^\infty\frac{(-1)^n}{\Gamma(\frac{n\alpha}{\tilde{\alpha}}+\alpha+\rho)}\frac{e^{\frac{nx}{\alpha}}}{n!}.
\end{align*}
When $\tilde{\alpha}=\alpha$ and $\rho>\frac{1}{2}$, the function $m_{H_\psi}\left(\cdot+\frac{{\rm{i}}}{2}   \right)\notin\bmrm[1]{L}(\mathbb{R})$ for $\rho\in (\frac{1}{2},1]$. In this case, we can use the same idea as in the proof of Proposition~\ref{prop:one_sided_jump}, where we have used the convolution of the integrand with respect to a class of kernel functions $\{\mathfrak{f}_\kappa, \kappa>1\}$ and recalling the  fact (see \eqref{eq:eigenfunction_1} with $\phi_+(s)=s+\alpha+\rho$) that
\begin{align*}
x\mapsto \sum_{n=0}^\infty \frac{(-1)^n}{\Gamma(n+\alpha+\rho)}\frac{e^{\frac{nx}{\alpha}}}{n!} \in \mathbf{C}_0(\mathbb{R}),
\end{align*}
we can conclude that
\begin{align*}
J_{\psi}(x)=\sum_{n=0}^\infty \frac{(-1)^n}{\Gamma(n+\alpha+\rho)}\frac{e^{\frac{nx}{\alpha}}}{n!}.
\end{align*}
When $\tilde{\alpha}<\alpha$, $\frac{1}{m_{H_\psi}}\left(\cdot+\frac{{\rm{i}}}{2}   \right)\in\bmrm{L}(\mathbb{R})$ and, from the proof of Theorem~\ref{thm:spectrum}, one gets
\begin{align*}
J_{\overline{\psi}}(x)=\frac{1}{\sqrt{2\pi}}\int_{-\infty-\frac{\mathrm{i}}{2}}^{\infty+\frac{{\rm{i}}}{2}   }\frac{\Gamma(\rho-i\alpha z)}{\Gamma(\tilde{\alpha}(1+{\rm{i}}z)   )}e^{{\rm{i}}zx}\,dz.
\end{align*}
The poles of the function $z\mapsto\frac{\Gamma(\rho-{\rm{i}}\alpha z)}{\Gamma(\tilde{\alpha}(1+{\rm{i}}z)   )}$ are $\{-\frac{n+\rho}{\alpha}{\rm{i}}, \ n\in\mathbb{N}\cup\{0\}\}$ with residues $\frac{1}{\alpha n!\Gamma(\tilde{\alpha}(1+\frac{n+\rho}{\alpha}))}$. Using the same argument as in the case $\tilde{\alpha}>\alpha$ and Cauchy's theorem of residues, \eqref{eq:co-eigenfunction_1} follows.
